name: CI
on:
  push:
    branches: [main]
  pull_request:
  workflow_dispatch:
permissions:
  contents: read
jobs:
  verify:
    runs-on: ubuntu-24.04
    timeout-minutes: 10
    steps:
      - uses: actions/checkout@d23441a48e516b6c34aea4fa41551a30e30af803 # v6
        with:
          persist-credentials: false
      - uses: actions/setup-node@249970729cb0ef3589644e2896645e5dc5ba9c38 # v6
        with:
          node-version: 24.14.0
          cache: npm
      - run: npm ci --ignore-scripts
      - run: npm run verify
===== src/catalog.js =====
export const products = [{
  id: 'lavazza-crema-e-gusto-vacuum-ground',
  name: 'Lavazza Crema e Gusto',
  form: 'Vacuum-packed ground coffee',
  targetMarket: 'IL',
  notes: 'Verify the exact blend and grams per pack from each vendor. Keep Classico, Forte and other variants separate. Exclude beans, capsules and pods.'
}];
===== src/index.js =====
import { products } from './catalog.js';

export default {
  async fetch(request, env) {
    const { pathname } = new URL(request.url);
    if (pathname === '/health') {
      return Response.json({ status: 'ok', stage: 'scaffold' });
    }
    if (pathname === '/api/catalog') {
      return Response.json({
        products,
        offers: [],
        status: 'Research pending. No verified vendor offers yet.',
        updatedAt: null
      }, { headers: { 'Cache-Control': 'public, max-age=60' } });
    }
    if (pathname.startsWith('/api/')) {
      return Response.json({ error: 'Not found' }, { status: 404 });
    }
    return env.ASSETS.fetch(request);
  }
};
===== tests/worker.test.js =====
import test from 'node:test';
import assert from 'node:assert/strict';
import worker from '../src/index.js';

test('bootstrap makes no invented price or availability claims', async () => {
  const response = await worker.fetch(new Request('https://example.test/api/catalog'));
  const data = await response.json();
  assert.equal(data.products[0].form, 'Vacuum-packed ground coffee');
  assert.equal(data.products[0].targetMarket, 'IL');
  assert.deepEqual(data.offers, []);
  assert.equal(data.updatedAt, null);
});

test('health route works and unknown API paths stay JSON 404s', async () => {
  assert.equal((await worker.fetch(new Request('https://example.test/health'))).status, 200);
  const response = await worker.fetch(new Request('https://example.test/api/missing'));
  assert.equal(response.status, 404);
  assert.deepEqual(await response.json(), { error: 'Not found' });
});

test('website requests reach Workers static assets', async () => {
  const request = new Request('https://example.test/');
  const result = await worker.fetch(request, { ASSETS: { fetch: async value => {
    assert.equal(value, request);
    return new Response('website');
  } } });
  assert.equal(await result.text(), 'website');
});
===== public/index.html =====
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <meta name="description" content="Online shopping availability and delivered prices for Israel. Starting with Lavazza Crema e Gusto vacuum-packed ground coffee.">
  <title>Attention shoppers. Happy hunting.</title>
  <link rel="stylesheet" href="/style.css">
</head>
<body>
  <header class="masthead"><span>IL / ONLINE ORDER BOARD</span><span>01 → COFFEE</span></header>
  <main>
    <section class="headline"><div class="arrow" aria-hidden="true">↘</div><h1>Attention<br>shoppers.</h1><p>Happy hunting.<br>Find your way to a better delivered price.</p></section>
    <section class="destination" aria-label="Shopping destination"><strong>Destination → Israel</strong><span>Item price + shipping. Every unknown stays visible.</span></section>
    <section class="board" aria-labelledby="coffee-title">
      <div class="section-label">01 / FIRST ON THE BOARD</div>
      <h2 id="coffee-title">Lavazza<br>Crema e Gusto</h2>
      <p class="product-form">Vacuum-packed ground coffee</p>
      <div class="notice"><strong>Research in progress</strong><p>No verified offers yet. Vendor availability, pack sizes and shipping to Israel will appear here after the first successful checks.</p></div>
    </section>
  </main>
  <footer><span>Attention shoppers. Happy hunting.</span><span>Prices must be checked at checkout.</span></footer>
</body>
</html>
===== public/style.css =====
:root { color-scheme: light; --ink: #111; --paper: #f4f3eb; --pending: #f4d900; }
* { box-sizing: border-box; }
body { margin: 0; background: var(--paper); color: var(--ink); font-family: Helvetica, Arial, sans-serif; }
.masthead, footer { display: flex; justify-content: space-between; gap: 24px; padding: 22px 4vw; font-weight: 700; font-size: 13px; }
.masthead { border-bottom: 3px solid var(--ink); }
.headline { display: grid; grid-template-columns: 18% 1fr; padding: 38px 4vw 46px; }
.arrow { font-size: clamp(75px, 14vw, 200px); line-height: 1; font-weight: 700; }
h1 { margin: 0; font-size: clamp(55px, 10vw, 145px); line-height: .91; letter-spacing: -.055em; font-weight: 700; }
.headline p { grid-column: 2; font-size: clamp(18px, 2.2vw, 30px); line-height: 1.2; margin: 24px 0 0; }
.destination { display: flex; justify-content: space-between; gap: 20px; padding: 24px 4vw; background: var(--ink); color: var(--paper); font-size: 16px; }
.board { margin: 48px 4vw 70px; display: grid; grid-template-columns: 25% 1fr; column-gap: 4vw; }
.section-label { border-top: 3px solid var(--ink); padding-top: 12px; font-size: 12px; font-weight: 700; }
h2 { margin: 0; border-top: 3px solid var(--ink); padding-top: 12px; font-size: clamp(32px, 5vw, 72px); letter-spacing: -.04em; line-height: 1; }
.product-form { grid-column: 2; margin: 20px 0 32px; font-size: 18px; }
.notice { grid-column: 2; border-top: 1px solid var(--ink); border-bottom: 1px solid var(--ink); padding: 20px; background: var(--pending); }
.notice strong { font-size: 22px; }
.notice p { max-width: 65ch; margin-bottom: 0; font-size: 16px; line-height: 1.5; }
footer { border-top: 3px solid var(--ink); font-size: 12px; }
@media (max-width: 640px) {
  .masthead { font-size: 10px; }
  .headline { grid-template-columns: 14% 1fr; padding: 30px 4vw; }
  .arrow { font-size: 60px; }
  .destination, footer { flex-direction: column; gap: 10px; }
  .board { grid-template-columns: 1fr; margin-top: 32px; }
  .section-label { border: 0; margin-bottom: 20px; }
  .product-form, .notice { grid-column: 1; }
}

