// Text, charset and HTML helpers shared by deterministic vendor adapters.
// Fetched pages are untrusted data. We only extract values with narrow patterns.

const WINDOWS_1255 = 'windows-1255';

export function decodeBuffer(bytes, charset) {
  const encodings = [];
  if (charset) encodings.push(charset.toLowerCase());
  encodings.push(WINDOWS_1255, 'utf-8');
  for (const encoding of encodings) {
    try {
      return new TextDecoder(encoding, { fatal: false }).decode(bytes);
    } catch {
      // Try the next candidate.
    }
  }
  return new TextDecoder('utf-8', { fatal: false }).decode(bytes);
}

/** Detect the declared charset from a meta tag, defaulting to UTF-8. */
export function declaredCharset(html) {
  const probe = html.slice(0, 4096).toLowerCase();
  const meta = /charset=["']?\s*([a-z0-9_-]+)/i.exec(probe);
  return meta ? meta[1] : 'utf-8';
}

export function decodeHtml(bytes, htmlHint = '') {
  const hint = declaredCharset(htmlHint || decodeBuffer(bytes, 'utf-8'));
  return decodeBuffer(bytes, hint);
}

export function stripTags(html) {
  return html.replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ');
}

export function collapse(text) {
  return text.replace(/\s+/g, ' ').trim();
}

export function textOf(html) {
  return collapse(stripTags(html));
}

export function firstMatch(text, pattern) {
  const match = pattern.exec(text);
  return match ? match[1] : null;
}

/** Parse a decimal number from a price-like string, tolerating thousands separators. */
export function parseDecimal(value) {
  if (value == null) return null;
  const cleaned = String(value).replace(/[^\d.,-]/g, '').replace(/,(?=\d{3}\b)/g, '');
  if (!/\d/.test(cleaned)) return null;
  const parsed = Number(cleaned.replace(',', '.'));
  return Number.isFinite(parsed) ? parsed : null;
}

/** Extract product/offer JSON from an application/ld+json script block. */
export function jsonLdBlocks(html) {
  const blocks = [];
  const pattern = /<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;
  let match;
  while ((match = pattern.exec(html)) !== null) {
    try {
      blocks.push(JSON.parse(match[1]));
    } catch {
      blocks.push(null);
    }
  }
  return blocks;
}

export function findJsonLd(html, type) {
  for (const block of jsonLdBlocks(html)) {
    const items = Array.isArray(block) ? block : [block];
    for (const item of items) {
      if (item && item['@type'] === type) return item;
    }
  }
  return null;
}

// Bounded HTTP fetching for the scheduled refresh pipeline.
// Public routes never call this with user-supplied URLs: hosts come from the
// vendor registry and every request has a timeout and a response size limit.

export const DEFAULT_HTTP_OPTIONS = {
  timeoutMs: 12_000,
  maxBytes: 1_500_000,
  userAgent: 'AttentionShoppersBot/0.1 (+https://github.com/igor-makarov/attention-shoppers-happy-hunting; shopping board refresh)'
};

export class FetchLimitError extends Error {}

export function hostAllowed(url, allowedHosts) {
  let host;
  try {
    host = new URL(url).hostname.toLowerCase();
  } catch {
    return false;
  }
  return allowedHosts.some(allowed => host === allowed || host.endsWith(`.${allowed}`));
}

/**
 * Create a fetch helper restricted to an explicit host allowlist.
 * Errors are returned, never thrown, so a broken source cannot abort a refresh.
 */
export function createBoundedFetcher({ fetchImpl = globalThis.fetch, allowedHosts = [], ...overrides } = {}) {
  const options = { ...DEFAULT_HTTP_OPTIONS, ...overrides };
  return async function fetchText(url, { accept, headers = {}, maxBytes } = {}) {
    if (!hostAllowed(url, allowedHosts)) {
      return { ok: false, status: 0, error: `host not allowed: ${safeHost(url)}`, bytes: 0 };
    }
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort('timeout'), options.timeoutMs);
    const limit = maxBytes ?? options.maxBytes;
    try {
      const response = await fetchImpl(url, {
        method: 'GET',
        redirect: 'follow',
        signal: controller.signal,
        headers: {
          'user-agent': options.userAgent,
          accept: accept ?? 'text/html,application/json;q=0.9,*/*;q=0.5',
          ...headers
        }
      });
      if (response.url && !hostAllowed(response.url, allowedHosts)) {
        return { ok: false, status: response.status, error: `redirect left allowlist: ${safeHost(response.url)}`, bytes: 0 };
      }
      const reader = response.body ? response.body.getReader() : null;
      const chunks = [];
      let bytes = 0;
      if (reader) {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          bytes += value.byteLength;
          if (bytes > limit) {
            controller.abort('size');
            return { ok: false, status: response.status, error: `response exceeded ${limit} bytes`, bytes };
          }
          chunks.push(value);
        }
      }
      const buffer = concat(chunks, bytes);
      return {
        ok: response.ok,
        status: response.status,
        url: response.url || url,
        contentType: response.headers.get('content-type') || '',
        bytes,
        buffer,
        text: new TextDecoder('utf-8', { fatal: false }).decode(buffer)
      };
    } catch (error) {
      const reason = controller.signal.aborted
        ? (String(controller.signal.reason) === 'size' ? 'response too large' : `timeout after ${options.timeoutMs}ms`)
        : `fetch failed: ${error?.message ?? error}`;
      return { ok: false, status: 0, error: reason, bytes: 0 };
    } finally {
      clearTimeout(timer);
    }
  };
}

function concat(chunks, total) {
  const out = new Uint8Array(total);
  let offset = 0;
  for (const chunk of chunks) {
    out.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return out;
}

function safeHost(url) {
  try {
    return new URL(url).hostname;
  } catch {
    return 'invalid-url';
  }
}

// Target products and strict listing classification.
//
// The board compares one product at a time. Classification is deliberately
// conservative: a listing that cannot be tied to Lavazza Crema e Gusto ground
// coffee in a vacuum brick is rejected instead of being merged into the board.

export const PRODUCTS = [
  {
    id: 'lavazza-crema-e-gusto-vacuum-ground',
    brand: 'Lavazza',
    line: 'Crema e Gusto',
    form: 'ground',
    packaging: 'vacuum brick',
    targetMarket: 'IL',
    notes: 'Ground coffee only. Beans, capsules, pods and machines are rejected. Classico, Forte, Ricco, Risveglio and decaf remain separate variants.'
  }
];

export const products = PRODUCTS;

export const VARIANTS = {
  classico: { id: 'classico', label: 'Classico', aliases: ['classico', 'classic', 'קלאסיקו', 'קלאסי'] },
  forte: { id: 'forte', label: 'Forte', aliases: ['forte', 'פורטה'] },
  ricco: { id: 'ricco', label: 'Ricco', aliases: ['ricco', 'ריקו'] },
  risveglio: { id: 'risveglio', label: 'Risveglio', aliases: ['risveglio', 'התעוררות'] },
  decaf: { id: 'decaf', label: 'Decaffeinated', aliases: ['decaf', 'decaffeinato', 'נטול קפאין', 'dek'] },
  unspecified: { id: 'unspecified', label: 'Variant not stated', aliases: [] }
};

const REJECT_FORMS = [
  { id: 'beans', pattern: /\b(beans?|whole\s*bean|פולי|bønner|boenner|kaffeebohnen|grain)\b/i, label: 'whole beans' },
  { id: 'capsules', pattern: /(capsul|קפסול|coffee\s*pods?|\bpods?\b|nespresso|dolce\s*gusto|senseo|a\s*modo\s*mio|\bese\b)/i, label: 'capsules or pods' },
  { id: 'machine', pattern: /(coffee\s*machin|מכונת\s*קפה|espresso\s*machine)/i, label: 'coffee machine' }
];

const GROUND_PATTERN = /(ground|טחון|macinato|molido|moulu|gemahlen|malet|filtro|filter\s*coffee)/i;
const BRAND_PATTERN = /(lavazza|לוואצה|לבאצה)/i;
const LINE_PATTERN = /(crema\s*(?:e|&|and|-)?\s*gusto|קרמה\s*אה\s*גוסטו|קרמה\s*גוסטו)/i;

/** Nominal product identity for the target listing. */
export function classifyListing(text) {
  const value = String(text || '').toLowerCase();
  const reasons = [];
  if (!BRAND_PATTERN.test(value)) reasons.push('brand is not Lavazza');
  if (!LINE_PATTERN.test(value)) reasons.push('line is not Crema e Gusto');
  const rejected = REJECT_FORMS.find(form => form.pattern.test(value));
  if (rejected) reasons.push(`listing is ${rejected.label}`);
  const ground = GROUND_PATTERN.test(value);
  if (!ground) reasons.push('listing does not state ground coffee');

  const variant = variantOf(value);
  const pack = parsePackSize(text);
  const matched = reasons.length === 0;

  return {
    matched,
    productId: matched ? PRODUCTS[0].id : null,
    variantId: variant.id,
    variantLabel: variant.label,
    form: matched ? 'ground' : (rejected ? rejected.id : 'unknown'),
    packGrams: pack.grams,
    packCount: pack.count,
    totalGrams: pack.grams != null ? pack.grams * pack.count : null,
    reasons: matched
      ? (pack.grams == null ? ['pack weight not stated; offer can be shown but not normalized'] : [])
      : reasons
  };
}

export function variantOf(text) {
  const value = String(text || '').toLowerCase();
  for (const variant of Object.values(VARIANTS)) {
    if (variant.id === 'unspecified') continue;
    if (variant.aliases.some(alias => value.includes(alias))) return variant;
  }
  return VARIANTS.unspecified;
}

const OZ_TO_GRAMS = 28.349523125;

/** Parse grams per pack and pack count from a listing name. */
export function parsePackSize(text) {
  const value = String(text || '');
  let grams = null;

  const ounce = /(\d+(?:[.,]\d+)?)\s*(?:-|\s)?(?:ounce|oz)\b/i.exec(value);
  if (ounce) {
    grams = round(Math.round(parseDecimalValue(ounce[1]) * OZ_TO_GRAMS));
  }
  if (grams == null) {
    const gram = /(\d{2,4}(?:[.,]\d+)?)\s*(?:גרם|גר'|ג'|ג׳|gr\b|g\b|grams?\b|grs\b|gramos\b)/i.exec(value);
    if (gram) grams = round(parseDecimalValue(gram[1]));
  }
  if (grams == null) {
    const kg = /(\d+(?:[.,]\d+)?)\s*(?:kg|ק"ג|קג|קילו)/i.exec(value);
    if (kg) grams = round(parseDecimalValue(kg[1]) * 1000);
  }

  let count = 1;
  const packOf = /pack\s*of\s*(\d{1,3})/i.exec(value);
  const multiply = /(\d{1,3})\s*(?:x|×)\s*\d{2,4}\s*(?:גרם|gr\b|g\b|grams?\b|oz\b|ounce)/i.exec(value);
  const hebrewPacks = /(\d{1,3})\s*(?:אריזות|חבילות|יחידות)/.exec(value);
  if (packOf) count = Number(packOf[1]);
  else if (multiply) count = Number(multiply[1]);
  else if (hebrewPacks) count = Number(hebrewPacks[1]);
  else if (grams == null) {
    const bareCount = /^(\d{1,3})\s*(?:אריזות|חבילות)/.exec(value.trim());
    if (bareCount) count = Number(bareCount[1]);
  }
  if (!Number.isFinite(count) || count < 1 || count > 99) count = 1;
  return { grams, count };
}

function parseDecimalValue(raw) {
  return Number(String(raw).replace(',', '.'));
}

function round(value) {
  return Math.round(value * 10) / 10;
}

// Exchange-rate handling.
//
// The public runtime never invents a conversion. Rates come from the Bank of
// Israel daily reference feed (www.boi.org.il/currency.xml, JSON) and are stored
// with their publication timestamp. When a rate is missing, an amount in that
// currency cannot be converted and the offer cannot be ranked.

export const FX_SOURCE = {
  name: 'Bank of Israel exchange rates',
  url: 'https://www.boi.org.il/currency.xml',
  note: 'Official daily reference rates published by the Bank of Israel.'
};

export const BASE_CURRENCY = 'ILS';

/** Parse the Bank of Israel JSON payload into a rate table. */
export function parseBoiRates(payload) {
  const entries = Array.isArray(payload?.exchangeRates) ? payload.exchangeRates : [];
  const rates = {};
  let asOf = null;
  for (const entry of entries) {
    if (!entry || typeof entry.key !== 'string') continue;
    const rate = Number(entry.currentExchangeRate);
    const unit = Number(entry.unit) || 1;
    if (!Number.isFinite(rate) || rate <= 0) continue;
    rates[entry.key.toUpperCase()] = { rate, unit };
    if (!asOf && typeof entry.lastUpdate === 'string') asOf = entry.lastUpdate;
  }
  if (Object.keys(rates).length === 0) return null;
  return { base: BASE_CURRENCY, asOf, rates, source: FX_SOURCE };
}

/**
 * Convert an amount to ILS using a stored rate table.
 * Returns { known:false } when the currency is missing; callers must not treat
 * a missing conversion as zero.
 */
export function toIls(amount, currency, fx) {
  if (amount == null || !Number.isFinite(Number(amount))) return { known: false, reason: 'amount unknown' };
  const code = String(currency || '').toUpperCase();
  if (code === BASE_CURRENCY) {
    return { known: true, amount: Number(amount), asOf: fx?.asOf ?? null, converted: false };
  }
  const entry = fx?.rates?.[code];
  if (!entry) {
    return { known: false, reason: `no ${code} reference rate stored`, asOf: fx?.asOf ?? null };
  }
  return {
    known: true,
    amount: (Number(amount) / entry.unit) * entry.rate,
    asOf: fx.asOf,
    converted: true,
    source: fx.source ?? FX_SOURCE
  };
}

export function formatIls(amount) {
  if (amount == null || !Number.isFinite(Number(amount))) return null;
  return `₪${Number(amount).toFixed(2)}`;
}

// Pure quote and ranking engine.
//
// Comparison total = item price + shipping + mandatory fees, normalized to ILS.
// Unknown shipping, unknown FX, stale observations, unknown availability and
// out-of-stock observations never become zero and never win.
// Pickup options are kept separate from delivered offers.

import { toIls } from './fx.js';

export const DEFAULT_STALE_AFTER_MS = 24 * 60 * 60 * 1000;
export const CLOCK_SKEW_MS = 5 * 60 * 1000;

export const DESTINATIONS = [
  { id: 'tel-aviv', label: 'Tel Aviv–Yafo', postcode: '6100000', country: 'IL' },
  { id: 'jerusalem', label: 'Jerusalem', postcode: '9100000', country: 'IL' },
  { id: 'haifa', label: 'Haifa', postcode: '3100000', country: 'IL' },
  { id: 'beer-sheva', label: "Be'er Sheva", postcode: '8400000', country: 'IL' },
  { id: 'eilat', label: 'Eilat', postcode: '8800000', country: 'IL' },
  { id: 'other', label: 'Elsewhere in Israel', postcode: null, country: 'IL' }
];

export function findDestination(id) {
  return DESTINATIONS.find(item => item.id === id) ?? DESTINATIONS[DESTINATIONS.length - 1];
}

const AVAILABILITY_LABELS = {
  in_stock: 'In stock (observed)',
  out_of_stock: 'Out of stock (observed)',
  unknown: 'Availability unknown'
};

export function quoteBoard({
  observations = [],
  productId,
  targetGrams = 500,
  destination = DESTINATIONS[0],
  fx = null,
  now = Date.now(),
  staleAfterMs = DEFAULT_STALE_AFTER_MS
} = {}) {
  const grams = clampGrams(targetGrams);
  const quotes = [];
  for (const observation of observations) {
    if (productId && observation?.product?.productId !== productId) continue;
    if (observation?.product?.form !== 'ground') continue;
    quotes.push(quoteOffer(observation, { grams, destination, fx, now, staleAfterMs }));
  }
  const ranked = quotes.filter(quote => quote.rankable).sort(compareQuotes);
  const pickup = quotes.filter(quote => quote.group === 'pickup');
  const unrankable = quotes.filter(quote => quote.group === 'unrankable');
  const staleOrUnavailable = quotes.filter(quote => quote.group === 'stale_unavailable');
  const unknown = [...unrankable, ...staleOrUnavailable];
  return {
    productId,
    targetGrams: grams,
    destination,
    generatedAt: new Date(now).toISOString(),
    fx: fx ? { asOf: fx.asOf ?? null, source: fx.source?.name ?? null } : null,
    best: ranked[0] ?? null,
    ranked,
    pickup,
    unrankable,
    staleOrUnavailable,
    unknown,
    counts: {
      observed: quotes.length,
      ranked: ranked.length,
      pickup: pickup.length,
      unknown: unknown.length
    }
  };
}

export function quoteOffer(observation, { grams, destination, fx, now, staleAfterMs }) {
  const product = observation.product ?? {};
  const price = observation.price ?? {};
  const shipping = observation.shipping ?? {};
  const reasons = [];
  const labels = [];

  const ageMs = observation.observedAt ? now - Date.parse(observation.observedAt) : null;
  const stale = ageMs == null || ageMs > staleAfterMs || ageMs < -CLOCK_SKEW_MS;
  const freshness = ageMs == null ? 'unknown' : stale ? 'stale' : 'fresh';

  const base = {
    key: observation.key,
    vendor: observation.vendor,
    itemUrl: observation.itemUrl,
    product: {
      productId: product.productId,
      name: product.name ?? null,
      variantId: product.variantId ?? 'unspecified',
      variantLabel: product.variantLabel ?? 'Variant not stated',
      form: product.form,
      packGrams: product.packGrams ?? null,
      packCount: product.packCount ?? 1,
      totalGrams: product.totalGrams ?? null,
      sku: product.sku ?? null
    },
    availability: observation.availability ?? 'unknown',
    availabilityLabel: AVAILABILITY_LABELS[observation.availability] ?? AVAILABILITY_LABELS.unknown,
    freshness,
    ageHours: ageMs == null ? null : Math.round((ageMs / 3_600_000) * 10) / 10,
    observedAt: observation.observedAt ?? null,
    attemptedAt: observation.attemptedAt ?? null,
    evidence: observation.evidence ?? [],
    units: null,
    orderedGrams: null,
    itemPrice: { amount: price.amount ?? null, currency: price.currency ?? null },
    itemTotalIls: null,
    shipping: {
      mode: shipping.mode ?? 'delivery',
      certainty: shipping.certainty ?? 'unknown',
      amount: shipping.amount?.amount ?? null,
      currency: shipping.amount?.currency ?? null,
      amountIls: null,
      freeThreshold: shipping.freeThreshold?.amount ?? null,
      freeThresholdCurrency: shipping.freeThreshold?.currency ?? null,
      minOrder: shipping.minOrder?.amount ?? null,
      minOrderCurrency: shipping.minOrder?.currency ?? null,
      destination: shipping.destination ?? { scope: 'country', country: 'IL' },
      note: shipping.note ?? null,
      evidence: shipping.evidence ?? null
    },
    mandatoryFees: [],
    totalIls: null,
    ilsPerKg: null,
    estimate: false,
    rankable: false,
    reasons,
    labels,
    group: 'unrankable'
  };

  if (observation.shipping?.mode === 'pickup') {
    base.group = 'pickup';
    base.labels.push('Pickup only — not a delivered offer');
    const pickupTotal = toIls(price.amount, price.currency, fx);
    if (pickupTotal.known && product.totalGrams) {
      base.itemTotalIls = round2(pickupTotal.amount);
      base.labels.push('Shown for pickup comparison only');
    }
    return base;
  }

  if (!product.totalGrams || !product.packGrams) {
    reasons.push('Pack weight is not stated, so the delivered price per kilogram cannot be calculated');
    return base;
  }

  const units = Math.max(1, Math.ceil(grams / product.totalGrams));
  base.units = units;
  base.orderedGrams = units * product.totalGrams;

  const itemTotal = toIls(price.amount == null ? null : price.amount * units, price.currency, fx);
  if (!itemTotal.known) {
    reasons.push(price.amount == null
      ? 'Item price was not observed'
      : `No ${price.currency} reference rate is stored, so the total cannot be converted to ILS`);
    if (price.amount != null && Number.isFinite(price.amount)) {
      base.itemPrice.amount = round2(price.amount * units);
    }
    return base;
  }
  base.itemTotalIls = round2(itemTotal.amount);
  if (itemTotal.converted) base.estimate = true;

  if (shipping.minOrder != null) {
    const min = toIls(shipping.minOrder, shipping.minOrderCurrency ?? price.currency, fx);
    if (min.known && base.itemTotalIls < min.amount - 0.005) {
      reasons.push(`Order is below the vendor minimum order of ${formatAmount(min.amount, 'ILS')}`);
      return base;
    }
  }

  const coverage = coverageProblem(shipping.destination, destination);
  if (coverage) {
    reasons.push(coverage);
    return base;
  }

  if (observation.availability === 'out_of_stock') {
    base.labels.push('Out of stock at last successful check');
    base.group = 'stale_unavailable';
    return base;
  }
  if (observation.availability !== 'in_stock') {
    reasons.push('Stock was not confirmed by the source, so this offer cannot be confirmed as available');
    base.group = 'stale_unavailable';
    return base;
  }

  const feeSum = { amount: 0, currency: 'ILS' };
  for (const fee of observation.mandatoryFees ?? []) {
    const converted = toIls(fee.amount, fee.currency, fx);
    if (!converted.known) {
      reasons.push(`A mandatory fee (${fee.label ?? 'unlabelled'}) could not be converted to ILS`);
      return base;
    }
    feeSum.amount += converted.amount;
    base.mandatoryFees.push({ label: fee.label ?? 'Mandatory fee', amountIls: round2(converted.amount) });
  }

  let shippingIls = null;
  if (shipping.certainty === 'unknown' || shipping.amount == null) {
    reasons.push(shipping.note
      ? `Shipping is not published before checkout (${shipping.note})`
      : 'Shipping is not published before checkout, so it is treated as unknown, not free');
    return base;
  }
  const convertedShipping = toIls(shipping.amount.amount ?? shipping.amount, shipping.amount.currency ?? price.currency, fx);
  if (!convertedShipping.known) {
    reasons.push(`Shipping is quoted in ${shipping.amount.currency ?? 'an unknown currency'} with no stored reference rate`);
    return base;
  }
  shippingIls = convertedShipping.amount;
  if (convertedShipping.converted || shipping.certainty === 'estimated') base.estimate = true;

  if (shipping.freeThreshold != null) {
    const threshold = toIls(shipping.freeThreshold.amount, shipping.freeThreshold.currency, fx);
    if (threshold.known && base.itemTotalIls >= threshold.amount - 0.005) {
      shippingIls = 0;
      base.labels.push(`Free shipping threshold met (${formatAmount(threshold.amount, 'ILS')})`);
    }
  }

  base.shipping.amountIls = round2(shippingIls);
  if (stale) {
    labels.push('Stale observation — the last successful check is too old to rank');
    base.group = 'stale_unavailable';
    return base;
  }

  base.totalIls = round2(base.itemTotalIls + shippingIls + feeSum.amount);
  base.ilsPerKg = round2((base.totalIls / base.orderedGrams) * 1000);
  base.rankable = true;
  base.group = 'ranked';
  if (base.estimate) labels.push('Estimate — includes a converted or estimated component');
  return base;
}

function coverageProblem(shippingDestination, destination) {
  if (!shippingDestination) return null;
  if (shippingDestination.scope === 'country') {
    if (destination?.country && shippingDestination.country !== destination.country) {
      return `Vendor does not deliver to ${destination.country}`;
    }
    return null;
  }
  if (shippingDestination.scope === 'localities') {
    const localities = shippingDestination.localities ?? [];
    if (!destination?.id || !localities.includes(destination.id)) {
      return `Vendor delivery list does not include ${destination?.label ?? 'this destination'}`;
    }
    return null;
  }
  return 'Vendor delivery coverage is not documented';
}

function compareQuotes(a, b) {
  if (a.totalIls !== b.totalIls) return a.totalIls - b.totalIls;
  if (a.ilsPerKg !== b.ilsPerKg) return a.ilsPerKg - b.ilsPerKg;
  return String(a.vendor?.name ?? '').localeCompare(String(b.vendor?.name ?? ''));
}

export function clampGrams(value) {
  const grams = Number(value);
  if (!Number.isFinite(grams) || grams <= 0) return 500;
  return Math.min(Math.max(Math.round(grams), 1), 100_000);
}

export function formatAmount(amount, currency = 'ILS') {
  const symbols = { ILS: '₪', USD: '$', EUR: '€', GBP: '£' };
  const symbol = symbols[String(currency).toUpperCase()] ?? `${currency} `;
  return `${symbol}${Number(amount).toFixed(2)}`;
}

function round2(value) {
  return Math.round(value * 100) / 100;
}

// Vendor adapter registry.
//
// Adapters are deterministic: fetch a fixed, allowlisted product URL, parse it
// with a versioned parser and return one observation per tracked offer. They
// never follow vendor content as instructions and never bypass access controls.
//
// Adding a vendor: create src/vendors/<id>.js exporting an adapter with
// { id, name, homepage, allowedHosts, parserVersion, offers, observe() } and
// register it here. Fixtures for its parser belong in tests/fixtures/.

import { pucks } from './pucks.js';
import { coffeeman } from './coffeeman.js';

export function registeredVendors() {
  return [coffeeman, pucks];
}

/** Every host any adapter may contact. Used for the refresh-time allowlist. */
export function vendorHosts(vendors = registeredVendors()) {
  return [...new Set(vendors.flatMap(vendor => vendor.allowedHosts))];
}

export function createObservation({ vendor, itemUrl, product, price, availability, availabilityEvidence, shipping, mandatoryFees = [], now }) {
  const observedAt = new Date(now ?? Date.now()).toISOString();
  const key = [
    vendor.id,
    product.sku ?? product.productId,
    product.variantId ?? 'unspecified',
    product.form,
    `${product.totalGrams ?? 'x'}g`,
    `x${product.packCount ?? 1}`
  ].join(':');
  return {
    key,
    vendor: { id: vendor.id, name: vendor.name, homepage: vendor.homepage },
    itemUrl,
    product,
    price,
    availability,
    availabilityEvidence: availabilityEvidence ?? null,
    shipping,
    mandatoryFees,
    observedAt,
    evidence: [
      { url: itemUrl, retrievedAt: observedAt, note: 'Item price and listed availability parsed from the vendor product page.' }
    ],
    parserVersion: vendor.parserVersion
  };
}

export function parseError(message, details) {
  const error = new Error(message);
  error.name = 'VendorParseError';
  if (details) error.details = details;
  return error;
}

// Pucks (pucks.co.il), Ramla, Israel — Lavazza Crema e Gusto Classico 250 g ground.
// Source of truth: schema.org Product JSON-LD on the public product page.
// Price and listed availability are observed. Shipping is only calculated at
// checkout, so it stays unknown and the offer cannot win the ranking.

import { classifyListing } from '../catalog.js';
import { findJsonLd, textOf } from '../lib/text.js';
import { createObservation, parseError } from './index.js';

const PRODUCT_URL = 'https://pucks.co.il/product/lavazza-crema-e-gusto-ground-coffee-250g';

const AVAILABILITY = {
  'https://schema.org/InStock': 'in_stock',
  'https://schema.org/LimitedAvailability': 'in_stock',
  'https://schema.org/OutOfStock': 'out_of_stock',
  'https://schema.org/SoldOut': 'out_of_stock'
};

export const pucks = {
  id: 'pucks',
  name: 'Pucks (פאקס)',
  homepage: 'https://pucks.co.il',
  allowedHosts: ['pucks.co.il', 'www.pucks.co.il'],
  parserVersion: 'pucks/1',
  offers: [{ id: 'classico-250g', url: PRODUCT_URL, kind: 'delivery' }],

  async observe({ fetchText, now }) {
    const observations = [];
    const failures = [];
    for (const offer of this.offers) {
      const response = await fetchText(offer.url, { accept: 'text/html' });
      if (!response.ok) {
        failures.push({ offerId: offer.id, url: offer.url, error: response.error ?? `HTTP ${response.status}` });
        continue;
      }
      try {
        observations.push(parsePucksProduct(response.text, { now }));
      } catch (error) {
        failures.push({ offerId: offer.id, url: offer.url, error: error.message, details: error.details ?? null });
      }
    }
    return { observations, failures };
  }
};

export function parsePucksProduct(html, { now } = {}) {
  const product = findJsonLd(html, 'Product');
  if (!product) throw parseError('No schema.org Product JSON-LD found', { url: PRODUCT_URL });
  const offer = product.offers ?? {};
  const name = String(product.name ?? '');
  const classification = classifyListing(name);
  if (!classification.matched) {
    throw parseError('Listing does not match the tracked product', { name, reasons: classification.reasons });
  }
  const priceAmount = Number(offer.price);
  if (!Number.isFinite(priceAmount)) throw parseError('Price missing from JSON-LD offer', { name, price: offer.price });
  const currency = String(offer.priceCurrency ?? '').toUpperCase();
  if (!currency) throw parseError('Currency missing from JSON-LD offer', { name });
  const availability = AVAILABILITY[String(offer.availability ?? '')] ?? 'unknown';

  const shippingNote = /המשלוח מחושב/.test(html)
    ? 'Shipping is calculated at checkout'
    : 'Shipping terms are not published on the product page';

  return createObservation({
    vendor: pucks,
    itemUrl: PRODUCT_URL,
    product: {
      productId: classification.productId,
      name,
      sku: product.sku ?? product.mpn ?? null,
      gtin: product.gtin13 ?? product.gtin ?? null,
      variantId: classification.variantId,
      variantLabel: classification.variantLabel,
      form: classification.form,
      packGrams: classification.packGrams,
      packCount: classification.packCount,
      totalGrams: classification.totalGrams,
      category: product.category ?? null
    },
    price: { amount: priceAmount, currency },
    availability,
    availabilityEvidence: {
      url: PRODUCT_URL,
      value: String(offer.availability ?? 'not stated'),
      note: 'Availability comes from the product page structured data, not from a price-only scrape.'
    },
    shipping: {
      mode: 'delivery',
      certainty: 'unknown',
      amount: null,
      destination: { scope: 'country', country: 'IL' },
      note: shippingNote,
      evidence: { url: PRODUCT_URL, retrievedAt: null, note: 'Store states shipping is calculated at checkout.' }
    },
    now
  });
}

export function pucksProductText(html) {
  return textOf(html).slice(0, 400);
}

// CoffeeMan / Amigo (coffeeman.co.il), Israel — Lavazza Crema e Gusto Classico 250 g ground.
// The page is a legacy Windows-1255 HTML document with schema.org microdata.
// Price, listed availability, SKU and the published delivery options are parsed
// from the product page. Free self-pickup is kept separate from home delivery.

import { classifyListing } from '../catalog.js';
import { decodeHtml, parseDecimal, stripTags, collapse } from '../lib/text.js';
import { createObservation, parseError } from './index.js';

const PRODUCT_URL = 'https://www.coffeeman.co.il/product/250-%D7%92%D7%A8%D7%9D-%D7%A7%D7%A4%D7%94-%D7%98%D7%97%D7%95%D7%9F-lavazza-crema-e-gusto-classico';

const AVAILABILITY = {
  InStock: 'in_stock',
  LimitedAvailability: 'in_stock',
  OutOfStock: 'out_of_stock',
  SoldOut: 'out_of_stock',
  PreOrder: 'unknown'
};

export const coffeeman = {
  id: 'coffeeman',
  name: 'CoffeeMan (אמיגו)',
  homepage: 'https://www.coffeeman.co.il',
  allowedHosts: ['www.coffeeman.co.il', 'coffeeman.co.il'],
  parserVersion: 'coffeeman/1',
  offers: [{ id: 'classico-250g', url: PRODUCT_URL, kind: 'delivery' }],

  async observe({ fetchText, now }) {
    const observations = [];
    const failures = [];
    for (const offer of this.offers) {
      const response = await fetchText(offer.url, { accept: 'text/html' });
      if (!response.ok) {
        failures.push({ offerId: offer.id, url: offer.url, error: response.error ?? `HTTP ${response.status}` });
        continue;
      }
      try {
        const html = response.buffer ? decodeHtml(response.buffer, response.text) : response.text;
        observations.push(parseCoffeemanProduct(html, { now }));
      } catch (error) {
        failures.push({ offerId: offer.id, url: offer.url, error: error.message, details: error.details ?? null });
      }
    }
    return { observations, failures };
  }
};

export function parseCoffeemanProduct(html, { now } = {}) {
  const name = extractName(html);
  if (!name) throw parseError('Product name not found', { url: PRODUCT_URL });
  const classification = classifyListing(name);
  if (!classification.matched) {
    throw parseError('Listing does not match the tracked product', { name, reasons: classification.reasons });
  }

  const priceMatch = /itemprop="price"[^>]*\bprice="([\d.,]+)"/.exec(html) ?? /itemprop="price"[^>]*\bcontent="([\d.,]+)"/.exec(html);
  const priceAmount = parseDecimal(priceMatch?.[1]);
  if (priceAmount == null) throw parseError('Price not found in product microdata', { name });
  const currency = /itemprop="priceCurrency"\s*>\s*([A-Z]{3})/.exec(html)?.[1] ?? null;
  if (!currency) throw parseError('Currency not found in product microdata', { name });

  const regularMatch = /\bprice="([\d.,]+)"\s+id="total_regularprice"/.exec(html) ?? /\bprice="([\d.,]+)"[^>]*class="toal_regularprice_view"/.exec(html);
  const regularPrice = parseDecimal(regularMatch?.[1]);

  const availabilityHref = /itemprop="availability"[^>]*href="([^"]+)"/.exec(html)?.[1] ?? '';
  const availability = AVAILABILITY[availabilityHref.split('/').pop()] ?? 'unknown';
  const sku = /itemprop="sku"[^>]*>([^<]+)</.exec(html)?.[1]?.trim()
    ?? /מקט:\s*(\d+)/.exec(html)?.[1]
    ?? null;
  const deliveryTime = collapse(/זמן\s*אספקה\s*:\s*([^<\n]+)/.exec(html)?.[1] ?? '');

  const shipping = parseShippingOptions(html);
  const observation = createObservation({
    vendor: coffeeman,
    itemUrl: PRODUCT_URL,
    product: {
      productId: classification.productId,
      name,
      sku,
      gtin: null,
      variantId: classification.variantId,
      variantLabel: classification.variantLabel,
      form: classification.form,
      packGrams: classification.packGrams,
      packCount: classification.packCount,
      totalGrams: classification.totalGrams,
      category: 'קפה טחון'
    },
    price: { amount: priceAmount, currency, regularAmount: regularPrice },
    availability,
    availabilityEvidence: {
      url: PRODUCT_URL,
      value: availabilityHref || 'not stated',
      note: 'Availability comes from the product page offer microdata, not from a price-only scrape.'
    },
    shipping: {
      mode: 'delivery',
      certainty: shipping.deliveryCents == null ? 'unknown' : 'verified',
      amount: shipping.deliveryCents == null ? null : { amount: shipping.deliveryCents, currency },
      destination: { scope: 'country', country: 'IL' },
      minOrder: null,
      freeThreshold: null,
      note: shipping.note,
      deliveryTime: deliveryTime || null,
      pickup: {
        available: shipping.pickupFree,
        amount: shipping.pickupFree ? { amount: 0, currency } : null,
        note: shipping.pickupFree ? 'Free self-pickup, listed on the product page.' : null
      },
      evidence: { url: PRODUCT_URL, retrievedAt: null, note: 'Delivery options are listed on the product page.' }
    },
    now
  });
  return observation;
}

export function parseShippingOptions(html) {
  const start = html.indexOf('delivery-price-product');
  const block = start >= 0 ? html.slice(start, start + 2500) : '';
  const items = [...block.matchAll(/<li[^>]*>([\s\S]*?)<\/li>/gi)].map(match => collapse(stripTags(match[1])));
  let deliveryCents = null;
  let pickupFree = false;
  let distributionCenter = null;
  for (const item of items) {
    if (item.includes('איסוף עצמי')) {
      pickupFree = true;
    } else if (item.includes('שליח')) {
      const amount = parseDecimal(item.match(/([\d.,]+)/)?.[1]);
      if (amount != null) deliveryCents = amount;
    } else if (item.includes('מרכז חלוקה')) {
      distributionCenter = item;
    }
  }
  const notes = [];
  if (deliveryCents != null) {
    notes.push(`Published courier delivery rate: ₪${deliveryCents.toFixed(2)}.`);
  } else {
    notes.push('No published courier rate found; delivery cost is unknown before checkout.');
  }
  if (distributionCenter) {
    notes.push('A distribution-center delivery option exists, but its price is not published on the product page.');
  }
  if (pickupFree) {
    notes.push('Free self-pickup is available and is kept separate from delivery.');
  }
  return { deliveryCents, pickupFree, distributionCenter, note: notes.join(' ') };
}

function extractName(html) {
  const h1 = /<h1[^>]*itemprop="name"[^>]*>([\s\S]*?)<\/h1>/i.exec(html)?.[1];
  if (h1) return collapse(stripTags(h1));
  const og = /<meta\s+property="og:title"\s+content\s*=\s*"([^"]+)"/i.exec(html)?.[1];
  if (og) return collapse(String(og).replace(/\s*-\s*₪[\d.,]+\s*$/, ''));
  const title = /<title>([\s\S]*?)<\/title>/i.exec(html)?.[1];
  return title ? collapse(stripTags(title).split('|')[0]) : null;
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
