// Vendor adapter registry.
//
// Adapters are deterministic: fetch a fixed, allowlisted product URL, parse it
// with a versioned parser and return one observation per tracked offer. They
// never follow vendor content as instructions and never bypass access controls.
//
// Adding a vendor: create src/vendors/<id>.js exporting an adapter with
// { id, name, homepage, allowedHosts, parserVersion, offers, observe() } and
// register it here. Fixtures for its parser belong in tests/fixtures/.

import { pucks } from './pucks.js';
import { coffeeman } from './coffeeman.js';

export function registeredVendors() {
  return [coffeeman, pucks];
}

/** Every host any adapter may contact. Used for the refresh-time allowlist. */
export function vendorHosts(vendors = registeredVendors()) {
  return [...new Set(vendors.flatMap(vendor => vendor.allowedHosts))];
}

export function createObservation({ vendor, itemUrl, product, price, availability, availabilityEvidence, shipping, mandatoryFees = [], now }) {
  const observedAt = new Date(now ?? Date.now()).toISOString();
  const key = [
    vendor.id,
    product.sku ?? product.productId,
    product.variantId ?? 'unspecified',
    product.form,
    `${product.totalGrams ?? 'x'}g`,
    `x${product.packCount ?? 1}`
  ].join(':');
  return {
    key,
    vendor: { id: vendor.id, name: vendor.name, homepage: vendor.homepage },
    itemUrl,
    product,
    price,
    availability,
    availabilityEvidence: availabilityEvidence ?? null,
    shipping,
    mandatoryFees,
    observedAt,
    evidence: [
      { url: itemUrl, retrievedAt: observedAt, note: 'Item price and listed availability parsed from the vendor product page.' }
    ],
    parserVersion: vendor.parserVersion
  };
}

export function parseError(message, details) {
  const error = new Error(message);
  error.name = 'VendorParseError';
  if (details) error.details = details;
  return error;
}

#!/usr/bin/env node
// Browser QA for the board using the installed headless Chrome via WebDriver.
//
//   node scripts/browser-qa.mjs [baseUrl]
//
// Default baseUrl is http://127.0.0.1:8789 (npm run dev). The script is
// dependency-free: it speaks the W3C WebDriver protocol over HTTP and writes
// screenshots and a JSON report to .shurik-local/qa/.

import { spawn } from 'node:child_process';
import { mkdir, writeFile } from 'node:fs/promises';
import { setTimeout as delay } from 'node:timers/promises';

const BASE = process.argv[2] ?? 'http://127.0.0.1:8789';
const OUT = '.shurik-local/qa';
const PORT = 9515;
const EMOJI = /[\u{1F300}-\u{1FAFF}\u{1F000}-\u{1F2FF}\u{2600}-\u{27BF}\u{FE0F}]/u;

const report = { base: BASE, startedAt: new Date().toISOString(), checks: [], consoleErrors: [] };
const check = (name, condition, detail = '') => {
  report.checks.push({ name, ok: Boolean(condition), detail });
  console.log(`${condition ? 'PASS' : 'FAIL'}  ${name}${detail ? ` — ${detail}` : ''}`);
};

const chrome = spawn('chromedriver', [`--port=${PORT}`, '--allowed-ips='], { stdio: ['ignore', 'pipe', 'pipe'] });
let session;
try {
  await waitFor(() => fetch(`http://127.0.0.1:${PORT}/status`).then(r => r.json()).then(() => true).catch(() => false), 15_000, 'chromedriver start');

  session = await webdriver('POST', '/session', {
    capabilities: {
      alwaysMatch: {
        browserName: 'chrome',
        'goog:chromeOptions': {
          binary: '/usr/bin/google-chrome',
          args: ['--headless=new', '--no-sandbox', '--disable-dev-shm-usage', '--disable-gpu', '--log-level=SEVERE']
        }
      }
    }
  });
  const sessionId = session.sessionId ?? session.value?.sessionId;
  const wd = (method, path, body) => webdriver(method, `/session/${sessionId}${path}`, body);

  await wd('POST', '/timeouts', { implicit: 0, pageLoad: 30_000, script: 20_000 });
  await mkdir(OUT, { recursive: true });

  // Desktop scenario.
  await wd('POST', '/window/rect', { width: 1440, height: 1000, x: 0, y: 0 });
  await wd('POST', '/url', { url: `${BASE}/?grams=500&dest=tel-aviv` });
  await waitForBoard(wd);
  const desktop = await evaluate(wd, `(() => ({
    bestVendor: document.querySelector('.best__vendor')?.textContent ?? null,
    bestTotal: document.querySelector('.best__total')?.textContent ?? null,
    perKg: document.querySelector('.best__perkg')?.textContent ?? null,
    statuses: [...document.querySelectorAll('.status')].map(n => n.textContent.trim()),
    bestLink: document.querySelector('.best a')?.href ?? null,
    unknownVendors: [...document.querySelectorAll('.unknown__vendor')].map(n => n.textContent.trim()),
    unknownReasons: [...document.querySelectorAll('.unknown__reason')].map(n => n.textContent.trim()),
    pickupRows: document.querySelectorAll('.pickup-row').length,
    rankedRows: document.querySelectorAll('table.compare tbody tr').length,
    visibleText: document.body.innerText,
    bidiFragments: document.querySelectorAll('[dir="auto"][lang="he"]').length,
    hasSkipLink: !!document.querySelector('.skip'),
    hasMain: !!document.querySelector('main'),
    quantityPressed: [...document.querySelectorAll('#quantity-group button')].map(b => [b.textContent.trim(), b.getAttribute('aria-pressed')]),
    destinationOptions: [...document.querySelectorAll('#destination option')].map(o => o.textContent.trim())
  }))()`);
  check('desktop: best vendor is CoffeeMan', /CoffeeMan/.test(desktop.bestVendor ?? ''), desktop.bestVendor);
  check('desktop: delivered total for 500 g is ₪91.00', desktop.bestTotal === '₪91.00', desktop.bestTotal);
  check('desktop: per-kilogram normalization is shown', /182/.test(desktop.perKg ?? ''), desktop.perKg);
  check('desktop: stock status has a written label', desktop.statuses.includes('In stock (observed)'), desktop.statuses.join(' | '));
  check('desktop: vendor link points at the product page', /coffeeman\.co\.il\/product\//.test(desktop.bestLink ?? ''), desktop.bestLink);
  check('desktop: unknown-shipping offer stays visible with a plain-language reason', /Shipping is not published before checkout/.test(desktop.unknownReasons.join(' ')), desktop.unknownReasons[0]);
  check('desktop: destination selector lists Israeli localities', desktop.destinationOptions.length >= 5, desktop.destinationOptions.join(' | '));
  check('desktop: quantity control marks 500 g pressed', desktop.quantityPressed.some(([label, pressed]) => label === '500 g' && pressed === 'true'), desktop.quantityPressed.join(' | '));
  check('desktop: no emoji in visible text', !EMOJI.test(desktop.visibleText), 'emoji scan');
  check('desktop: Hebrew vendor text is direction-isolated', desktop.bidiFragments >= 1, String(desktop.bidiFragments));
  check('desktop: skip link and main landmark are present', desktop.hasSkipLink && desktop.hasMain, `skip=${desktop.hasSkipLink} main=${desktop.hasMain}`);
  await screenshot(wd, 'desktop-1440.png');

  // Quantity interaction: click "1 kg".
  const kgButton = await wd('POST', '/element', { using: 'css selector', value: '#quantity-group button[data-grams="1000"]' });
  await wd('POST', `/element/${elementId(kgButton)}/click`, {});
  await waitForPage(wd, `document.querySelector('.best__total')?.textContent === '₪157.00'`, 15_000, 'quantity update to 1 kg', `({total: document.querySelector('.best__total')?.textContent ?? null, search: location.search, pressed: [...document.querySelectorAll('#quantity-group button')].map(b => b.getAttribute('aria-pressed'))})`);
  const kgState = await evaluate(wd, `({
    total: document.querySelector('.best__total')?.textContent,
    perKg: document.querySelector('.best__perkg')?.textContent,
    url: location.search
  })`);
  check('interaction: 1 kg updates the delivered total to ₪157.00', kgState.total === '₪157.00', JSON.stringify(kgState));
  check('interaction: per-kg price recalculated', /157/.test(kgState.perKg ?? ''), kgState.perKg);
  check('interaction: quantity is reflected in the shareable URL', /grams=1000/.test(kgState.url ?? ''), kgState.url);

  // Destination change.
  await evaluate(wd, `(() => { const select = document.getElementById('destination'); select.value = 'eilat'; select.dispatchEvent(new Event('change', { bubbles: true })); return true; })()`);
  await waitForPage(wd, `document.querySelector('.section__intro')?.textContent.includes('Eilat')`, 15_000, 'destination update');
  const eilat = await evaluate(wd, `({ intro: document.querySelector('.section__intro')?.textContent, total: document.querySelector('.best__total')?.textContent })`);
  check('interaction: destination change recalculates for Eilat', /Eilat/.test(eilat.intro ?? ''), eilat.intro);

  // Unknown toggle.
  await evaluate(wd, `(() => { const box = document.getElementById('show-unknown'); box.checked = false; box.dispatchEvent(new Event('change', { bubbles: true })); return true; })()`);
  await waitForPage(wd, `!document.getElementById('unknown')`, 15_000, 'unknown section hidden');
  const hiddenUnknown = await evaluate(wd, `document.getElementById('unknown') === null`);
  check('interaction: unrankable offers can be hidden but are visible by default', hiddenUnknown === true);
  await evaluate(wd, `(() => { const box = document.getElementById('show-unknown'); box.checked = true; box.dispatchEvent(new Event('change', { bubbles: true })); return true; })()`);
  await waitForPage(wd, `!!document.getElementById('unknown')`, 15_000, 'unknown section restored');

  // Keyboard: focus the first quantity button, Tab to the next, then activate it with Enter.
  await evaluate(wd, `(() => { document.querySelector('#quantity-group button[data-grams="250"]').focus(); return true; })()`);
  await wd('POST', '/actions', { actions: [{ type: 'key', id: 'keyboard', actions: [{ type: 'keyDown', value: '\uE004' }, { type: 'keyUp', value: '\uE004' }] }] });
  const keyboard = await evaluate(wd, `(() => {
    const active = document.activeElement;
    const style = getComputedStyle(active);
    return { tag: active.tagName, label: active.textContent, outlineStyle: style.outlineStyle, outlineWidth: style.outlineWidth };
  })()`);
  check('keyboard: Tab moves focus to the next quantity button', keyboard.tag === 'BUTTON' && keyboard.label === '500 g', JSON.stringify(keyboard));
  check('keyboard: focused control shows a visible outline', keyboard.outlineStyle !== 'none' && parseFloat(keyboard.outlineWidth) >= 2, `${keyboard.outlineStyle} ${keyboard.outlineWidth}`);
  await wd('POST', '/actions', { actions: [{ type: 'key', id: 'keyboard', actions: [{ type: 'keyDown', value: '\uE007' }, { type: 'keyUp', value: '\uE007' }] }] });
  await waitForPage(wd, `document.querySelector('.best__total')?.textContent === '₪91.00'`, 15_000, 'keyboard activation of the 500 g quantity', `({total: document.querySelector('.best__total')?.textContent ?? null, search: location.search})`);
  check('keyboard: Enter activates the focused quantity and updates the total', true, 'total ₪91.00');
  await wd('DELETE', '/actions');

  // Mobile scenario.
  await wd('POST', '/window/rect', { width: 390, height: 844, x: 0, y: 0 });
  await wd('POST', '/url', { url: `${BASE}/?grams=500&dest=tel-aviv` });
  await waitForBoard(wd);
  const mobile = await evaluate(wd, `(() => {
    const rect = document.querySelector('.best').getBoundingClientRect();
    const controls = getComputedStyle(document.querySelector('.controls')).gridTemplateColumns;
    const table = document.querySelector('table.compare');
    const bodyOverflow = document.documentElement.scrollWidth > window.innerWidth + 1;
    return {
      bestFits: rect.width <= window.innerWidth + 1,
      controlColumns: controls,
      tableScrolls: table ? table.closest('.table-wrap').scrollWidth > table.closest('.table-wrap').clientWidth : 'no table',
      bodyOverflow,
      minTap: Math.min(...[...document.querySelectorAll('#quantity-group button')].map(b => b.getBoundingClientRect().height))
    };
  })()`);
  check('mobile: best-choice panel fits the viewport', mobile.bestFits === true, JSON.stringify(mobile));
  check('mobile: controls reflow to a single column', !mobile.controlColumns.includes(' '), mobile.controlColumns);
  check('mobile: page does not scroll horizontally', mobile.bodyOverflow === false, JSON.stringify(mobile));
  check('mobile: quantity buttons keep a 44px touch target', mobile.minTap >= 44, String(mobile.minTap));
  await screenshot(wd, 'mobile-390.png');

  // Close the session, then remove the driver's child processes before exiting.
  await wd('DELETE', '');
  report.sessionClosed = true;
} catch (error) {
  report.error = error?.stack ?? String(error);
  console.error('browser QA error:', error);
} finally {
  chrome.kill('SIGTERM');
  report.finishedAt = new Date().toISOString();
  report.failed = !report.checks.every(item => item.ok) || Boolean(report.error);
  await mkdir(OUT, { recursive: true });
  await writeFile(`${OUT}/report.json`, `${JSON.stringify(report, null, 2)}\n`);
  console.log(`\n${report.checks.filter(c => c.ok).length}/${report.checks.length} checks passed; report: ${OUT}/report.json`);
  // Explicit exit so a lingering browser/driver child handle cannot keep the runner busy.
  process.exit(report.failed ? 1 : 0);
}

async function webdriver(method, path, body) {
  const response = await fetch(`http://127.0.0.1:${PORT}${path}`, {
    method,
    headers: body ? { 'content-type': 'application/json' } : {},
    body: body ? JSON.stringify(body) : undefined,
    signal: AbortSignal.timeout(30_000)
  });
  const payload = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(`${method} ${path} -> ${response.status} ${JSON.stringify(payload)}`);
  return payload;
}

/** W3C WebDriver returns the element key `element-6066-...`; legacy drivers use `ELEMENT`. */
function elementId(found) {
  const value = found?.value ?? {};
  const id = value['element-6066-11e4-a52e-4f735466cecf'] ?? value.ELEMENT;
  if (!id) throw new Error(`element not found: ${JSON.stringify(found).slice(0, 200)}`);
  return id;
}

async function evaluate(wd, script) {
  const expression = script.trim().startsWith('return') ? script : `return ${script}`;
  const result = await wd('POST', '/execute/sync', { script: expression, args: [] });
  return result.value;
}

async function waitFor(predicate, timeoutMs, label) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    if (await predicate()) return true;
    await delay(250);
  }
  throw new Error(`timeout waiting for ${label}`);
}

/** Poll a page-side expression until it is truthy; report page state on timeout. */
async function waitForPage(wd, expression, timeoutMs, label, probe) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    try {
      if (await evaluate(wd, expression)) return true;
    } catch {
      // Transient evaluate failures (for example during a re-render) are retried.
    }
    await delay(250);
  }
  let detail = '';
  if (probe) {
    try {
      detail = `; page state: ${JSON.stringify(await evaluate(wd, probe))}`;
    } catch (error) {
      detail = `; page state unavailable: ${error?.message ?? error}`;
    }
  }
  throw new Error(`timeout waiting for ${label}${detail}`);
}

async function waitForBoard(wd) {
  await waitFor(async () => evaluate(wd, `document.body.dataset.boardState === 'ready' && !!document.querySelector('.best, .empty')`), 20_000, 'board render');
}

async function screenshot(wd, name) {
  const shot = await wd('GET', '/screenshot');
  await writeFile(`${OUT}/${name}`, Buffer.from(shot.value, 'base64'));
}

// Public Worker: read-only comparison board plus the scheduled refresh entry.
//
// Public routes only read the persisted snapshot. They never fetch vendor URLs
// supplied by a visitor and never trigger unbounded scraping. The first request
// after a deployment may start one throttled initial refresh.

import { products, PRODUCTS } from './catalog.js';
import { quoteBoard, findDestination, DESTINATIONS } from './lib/quote.js';
import { runRefresh, maybeInitialRefresh } from './refresh.js';
import { durableStore, storeClient } from './store.js';
import { registeredVendors } from './vendors/index.js';

export { BoardStore } from './store.js';

const PUBLIC_CACHE = 'public, max-age=300, stale-while-revalidate=3600';
const DEFAULT_VARIANT = 'classico';

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    if (request.method !== 'GET' && request.method !== 'HEAD') {
      return Response.json({ error: 'Method not allowed' }, { status: 405, headers: { allow: 'GET, HEAD' } });
    }
    if (url.pathname === '/health') {
      scheduleInitialRefresh(env, ctx);
      return handleHealth(env);
    }
    if (url.pathname === '/api/catalog') {
      return json({ products, destinations: DESTINATIONS, vendors: publicVendors() });
    }
    if (url.pathname === '/api/board') {
      scheduleInitialRefresh(env, ctx);
      return handleBoard(request, env, ctx, url);
    }
    if (url.pathname === '/api/status') {
      return handleStatus(env);
    }
    if (url.pathname.startsWith('/api/')) {
      return json({ error: 'Not found' }, 404);
    }
    if (env.ASSETS) return env.ASSETS.fetch(request);
    return new Response('Not found', { status: 404 });
  },

  async scheduled(event, env, ctx) {
    const store = storeClient(durableStore(env));
    const job = runRefresh({ store, trigger: event?.cron ? 'cron' : 'scheduled' });
    if (ctx?.waitUntil) ctx.waitUntil(job);
    return job;
  }
};

function json(body, status = 200, headers = {}) {
  return Response.json(body, { status, headers: { 'Cache-Control': PUBLIC_CACHE, ...headers } });
}

async function handleHealth(env) {
  let refresh = null;
  let error = null;
  try {
    if (env.BOARD) {
      const store = storeClient(durableStore(env));
      const meta = await store.getMeta('lastRefreshAt');
      refresh = meta?.value ?? null;
    }
  } catch (cause) {
    error = 'storage unavailable';
  }
  return json({ status: 'ok', stage: 'live', lastRefreshAt: refresh, storageError: error });
}

async function handleBoard(request, env, ctx, url) {
  if (!env.BOARD) {
    return json({
      status: 'storage not configured',
      offers: [],
      message: 'The board needs the BOARD Durable Object binding from docs/DEPLOYMENT.md.'
    });
  }
  const store = storeClient(durableStore(env));
  const productId = url.searchParams.get('product') ?? PRODUCTS[0].id;
  const variantId = url.searchParams.get('variant') ?? DEFAULT_VARIANT;
  const grams = url.searchParams.get('grams') ?? '500';
  const destination = findDestination(url.searchParams.get('dest'));
  const snapshot = await store.snapshot();
  const board = quoteBoard({
    observations: snapshot.observations,
    productId,
    variantId,
    targetGrams: grams,
    destination,
    fx: snapshot.meta?.fx ?? null,
    now: Date.now()
  });
  const vendors = snapshot.vendors ?? {};
  return json({
    ...board,
    product: products.find(item => item.id === productId) ?? null,
    freshness: {
      lastRefreshAt: snapshot.meta?.lastRefreshAt?.value ?? null,
      fx: snapshot.meta?.fx ? { asOf: snapshot.meta.fx.asOf, fetchedAt: snapshot.meta.fx.fetchedAt, source: snapshot.meta.fx.source?.name ?? null } : null,
      vendors: Object.values(vendors).map(state => ({
        vendorId: state.vendorId,
        lastAttemptAt: state.lastAttemptAt,
        lastSuccessAt: state.lastSuccessAt,
        consecutiveFailures: state.consecutiveFailures,
        nextAttemptAt: state.nextAttemptAt,
        lastErrors: state.lastErrors ?? []
      }))
    },
    status: board.ranked.length > 0
      ? 'Delivered totals ranked from verified observations.'
      : 'No offer currently has enough verified information to rank. Unknowns are listed below.'
  }, 200, {
    'Vary': 'Accept-Encoding',
    'Access-Control-Allow-Origin': '*'
  });
}

async function handleStatus(env) {
  if (!env.BOARD) return json({ status: 'storage not configured', vendors: [], runs: [] });
  const store = storeClient(durableStore(env));
  const snapshot = await store.snapshot();
  return json({
    lastRefreshAt: snapshot.meta?.lastRefreshAt?.value ?? null,
    fx: snapshot.meta?.fx ? { asOf: snapshot.meta.fx.asOf, fetchedAt: snapshot.meta.fx.fetchedAt } : null,
    vendors: Object.values(snapshot.vendors ?? {}).map(state => ({
      vendorId: state.vendorId,
      lastAttemptAt: state.lastAttemptAt,
      lastSuccessAt: state.lastSuccessAt,
      consecutiveFailures: state.consecutiveFailures,
      nextAttemptAt: state.nextAttemptAt,
      lastErrors: state.lastErrors ?? []
    })),
    runs: (snapshot.runs ?? []).map(run => ({
      trigger: run.trigger,
      startedAt: run.startedAt,
      finishedAt: run.finishedAt,
      requests: run.requests,
      vendors: run.vendors
    })),
    observations: snapshot.observations.length
  });
}

function publicVendors() {
  return registeredVendors().map(vendor => ({
    id: vendor.id,
    name: vendor.name,
    homepage: vendor.homepage,
    offers: vendor.offers.map(offer => ({ id: offer.id, url: offer.url, kind: offer.kind }))
  }));
}

function scheduleInitialRefresh(env, ctx) {
  const work = triggerInitialRefreshIfNeeded(env, ctx)
    .catch(error => console.warn('initial refresh trigger failed:', error?.stack ?? error));
  if (ctx?.waitUntil) ctx.waitUntil(work);
  return work;
}

export async function triggerInitialRefreshIfNeeded(env, ctx) {
  if (!env.BOARD) return { skipped: true, reason: 'no storage binding' };
  const store = storeClient(durableStore(env));
  return maybeInitialRefresh({ store, ctx });
}

#!/usr/bin/env node
// Repeatable local cron simulation.
//
//   npm run cron:local            # real vendor + Bank of Israel checks, persisted to .shurik-local/board.json
//   npm run cron:offline          # same pipeline with recorded fixtures, no network
//
// The Worker's scheduled handler calls the same runRefresh() function, so this
// script exercises the production refresh path without any Cloudflare account.

import { runRefresh } from '../src/refresh.js';
import { createFileStore } from '../src/store.js';
import { registeredVendors } from '../src/vendors/index.js';
import { readFile } from 'node:fs/promises';

const args = new Set(process.argv.slice(2));
const offline = args.has('--offline');
const storePath = process.env.BOARD_STATE_PATH ?? '.shurik-local/board.json';
const now = args.has('--simulate-failure-now') ? Date.now() + 24 * 60 * 60 * 1000 : Date.now();

const store = await createFileStore(storePath);

if (offline) {
  const fixtures = new URL('../tests/fixtures/', import.meta.url);
  const coffeemanBytes = await readFile(new URL('coffeeman-product.windows-1255.html', fixtures));
  const pucksHtml = await readFile(new URL('pucks-product.html', fixtures), 'utf8');
  const boi = {
    exchangeRates: [
      { key: 'USD', currentExchangeRate: 3.0, unit: 1, lastUpdate: '2026-10-09T09:21:04.476265Z' },
      { key: 'EUR', currentExchangeRate: 3.5, unit: 1, lastUpdate: '2026-10-09T09:21:04.476265Z' }
    ]
  };
  globalThis.__offlineFetch = async url => {
    if (url.includes('coffeeman.co.il')) {
      return new Response(coffeemanBytes, { status: 200, headers: { 'content-type': 'text/html; charset=windows-1255' } });
    }
    if (url.includes('pucks.co.il')) {
      return new Response(pucksHtml, { status: 200, headers: { 'content-type': 'text/html; charset=utf-8' } });
    }
    if (url.includes('boi.org.il')) {
      return Response.json(boi);
    }
    return new Response('not found', { status: 404 });
  };
}

const fetchImpl = offline ? globalThis.__offlineFetch : globalThis.fetch;
const logger = { info: message => process.stderr.write(`${message}\n`), warn: message => process.stderr.write(`${message}\n`) };

try {
  const summary = await runRefresh({
    store,
    vendors: registeredVendors(),
    fetchImpl,
    now,
    trigger: offline ? 'cron-simulation-offline' : 'cron-simulation',
    logger
  });
  await store.flush();
  const snapshot = await store.snapshot();
  console.log(JSON.stringify({
    mode: offline ? 'offline fixtures' : 'live sources',
    statePath: storePath,
    summary,
    offers: snapshot.observations.map(observation => ({
      key: observation.key,
      vendor: observation.vendor?.name,
      price: observation.price,
      availability: observation.availability,
      shipping: observation.shipping?.amount,
      shippingCertainty: observation.shipping?.certainty,
      observedAt: observation.observedAt,
      lastError: observation.lastError ?? null
    })),
    fx: snapshot.meta.fx ? { asOf: snapshot.meta.fx.asOf, fetchedAt: snapshot.meta.fx.fetchedAt, usd: snapshot.meta.fx.rates?.USD } : null
  }, null, 2));
  process.exitCode = summary.skipped ? 0 : 0;
} catch (error) {
  console.error('cron simulation failed:', error);
  process.exitCode = 1;
}

// Persistence for the self-updating board.
//
// Production uses a SQLite-backed Durable Object (class BoardStore) so the
// deployment can define its own storage without CF administration credentials
// in GitHub. The same method names are implemented by an in-memory store and a
// file-backed store for tests and the local cron simulation.

const SCHEMA = [
  `CREATE TABLE IF NOT EXISTS observations (
     key TEXT PRIMARY KEY,
     payload TEXT NOT NULL,
     observed_at TEXT,
     attempted_at TEXT,
     last_error TEXT
   )`,
  `CREATE TABLE IF NOT EXISTS vendor_state (
     vendor_id TEXT PRIMARY KEY,
     payload TEXT NOT NULL
   )`,
  `CREATE TABLE IF NOT EXISTS meta (
     key TEXT PRIMARY KEY,
     value TEXT NOT NULL
   )`,
  `CREATE TABLE IF NOT EXISTS runs (
     id INTEGER PRIMARY KEY AUTOINCREMENT,
     payload TEXT NOT NULL,
     started_at TEXT,
     finished_at TEXT
   )`
];

export const STORE_INTERFACE = [
  'listObservations', 'putObservation', 'markAttempt',
  'getVendorState', 'setVendorState', 'getMeta', 'setMeta',
  'recordRun', 'listRuns', 'acquireLease', 'releaseLease'
];

export class BoardStore {
  constructor(state) {
    this.state = state;
    this.storage = state.storage;
    this.sql = state.storage.sql;
    for (const statement of SCHEMA) this.sql.exec(statement);
    this.methods = {
      snapshot: () => this.snapshot(),
      listObservations: () => this.listObservations(),
      putObservation: args => this.putObservation(args[0]),
      markAttempt: args => this.markAttempt(args[0]),
      getVendorState: args => this.getVendorState(args[0]),
      setVendorState: args => this.setVendorState(args[0], args[1]),
      getMeta: args => this.getMeta(args[0]),
      setMeta: args => this.setMeta(args[0], args[1]),
      recordRun: args => this.recordRun(args[0]),
      listRuns: args => this.listRuns(args[0] ?? 10),
      acquireLease: args => this.acquireLease(args[0], args[1], args[2]),
      releaseLease: args => this.releaseLease(args[0])
    };
  }

  async fetch(request) {
    if (request.method !== 'POST') return new Response('Method not allowed', { status: 405 });
    let body;
    try {
      body = await request.json();
    } catch {
      return Response.json({ error: 'invalid JSON body' }, { status: 400 });
    }
    const method = this.methods[body?.op];
    if (!method) return Response.json({ error: `unknown op ${body?.op}` }, { status: 400 });
    try {
      return Response.json({ result: await method(body.args ?? []) });
    } catch (error) {
      return Response.json({ error: error?.message ?? String(error) }, { status: 500 });
    }
  }

  async listObservations() {
    return this.sql.exec('SELECT key, payload, observed_at, attempted_at, last_error FROM observations').toArray()
      .map(row => ({
        ...JSON.parse(row.payload),
        key: row.key,
        observedAt: row.observed_at,
        attemptedAt: row.attempted_at,
        lastError: row.last_error
      }));
  }

  async putObservation(observation) {
    this.sql.exec(
      `INSERT INTO observations (key, payload, observed_at, attempted_at, last_error)
       VALUES (?, ?, ?, ?, NULL)
       ON CONFLICT(key) DO UPDATE SET payload = excluded.payload, observed_at = excluded.observed_at, attempted_at = excluded.attempted_at, last_error = NULL`,
      observation.key,
      JSON.stringify(observation),
      observation.observedAt ?? null,
      observation.attemptedAt ?? observation.observedAt ?? null
    );
  }

  async markAttempt({ key, attemptedAt, error }) {
    this.sql.exec('UPDATE observations SET attempted_at = ?, last_error = ? WHERE key = ?', attemptedAt, error ?? null, key);
    this.sql.exec(
      `INSERT INTO observations (key, payload, observed_at, attempted_at, last_error)
       SELECT ?, ?, NULL, ?, ? WHERE NOT EXISTS (SELECT 1 FROM observations WHERE key = ?)`,
      key, '{}', attemptedAt, error ?? null, key
    );
  }

  async snapshot() {
    return {
      observations: await this.listObservations(),
      vendors: this.listVendorState(),
      runs: await this.listRuns(5),
      meta: this.allMeta()
    };
  }

  listVendorState() {
    const out = {};
    for (const row of this.sql.exec('SELECT vendor_id, payload FROM vendor_state').toArray()) {
      out[row.vendor_id] = JSON.parse(row.payload);
    }
    return out;
  }

  allMeta() {
    const out = {};
    for (const row of this.sql.exec('SELECT key, value FROM meta').toArray()) {
      out[row.key] = JSON.parse(row.value);
    }
    return out;
  }

  async getVendorState(vendorId) {
    const row = this.sql.exec('SELECT payload FROM vendor_state WHERE vendor_id = ?', vendorId).toArray()[0];
    return row ? JSON.parse(row.payload) : null;
  }

  async setVendorState(vendorId, value) {
    this.sql.exec(
      `INSERT INTO vendor_state (vendor_id, payload) VALUES (?, ?)
       ON CONFLICT(vendor_id) DO UPDATE SET payload = excluded.payload`,
      vendorId, JSON.stringify(value)
    );
  }

  async getMeta(key) {
    const row = this.sql.exec('SELECT value FROM meta WHERE key = ?', key).toArray()[0];
    return row ? JSON.parse(row.value) : null;
  }

  async setMeta(key, value) {
    this.sql.exec(
      `INSERT INTO meta (key, value) VALUES (?, ?)
       ON CONFLICT(key) DO UPDATE SET value = excluded.value`,
      key, JSON.stringify(value)
    );
  }

  async recordRun(run) {
    this.sql.exec('INSERT INTO runs (payload, started_at, finished_at) VALUES (?, ?, ?)', JSON.stringify(run), run.startedAt ?? null, run.finishedAt ?? null);
  }

  async listRuns(limit = 10) {
    return this.sql.exec('SELECT payload FROM runs ORDER BY id DESC LIMIT ?', limit).toArray().map(row => JSON.parse(row.payload));
  }

  async acquireLease(name, holderId, ttlMs) {
    const current = await this.getMeta(`lease:${name}`);
    const now = Date.now();
    if (current && current.expiresAt > now && current.holderId !== holderId) return false;
    await this.setMeta(`lease:${name}`, { holderId, expiresAt: now + ttlMs, acquiredAt: new Date(now).toISOString() });
    return true;
  }

  async releaseLease(name) {
    await this.setMeta(`lease:${name}`, null);
  }
}

/** Client for the DO; safe to call from a Worker request or scheduled handler. */
export function durableStore(env) {
  const id = env.BOARD.idFromName('board');
  return env.BOARD.get(id);
}

export async function callStore(stub, op, args = []) {
  const response = await stub.fetch('https://board.internal/', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ op, args })
  });
  const payload = await response.json();
  if (!response.ok) throw new Error(payload?.error ?? `store error ${response.status}`);
  return payload.result;
}

export function storeClient(stub) {
  const call = (op, ...args) => callStore(stub, op, args);
  return {
    listObservations: () => call('listObservations'),
    putObservation: observation => call('putObservation', observation),
    markAttempt: attempt => call('markAttempt', attempt),
    getVendorState: vendorId => call('getVendorState', vendorId),
    setVendorState: (vendorId, value) => call('setVendorState', vendorId, value),
    getMeta: key => call('getMeta', key),
    setMeta: (key, value) => call('setMeta', key, value),
    recordRun: run => call('recordRun', run),
    listRuns: limit => call('listRuns', limit),
    acquireLease: (name, holderId, ttlMs) => call('acquireLease', name, holderId, ttlMs),
    releaseLease: name => call('releaseLease', name),
    snapshot: () => call('snapshot')
  };
}

/** In-memory implementation with the same interface, used by tests. */
export function createMemoryStore(initial = {}) {
  const observations = new Map();
  for (const observation of initial.observations ?? []) observations.set(observation.key, observation);
  const vendors = new Map(Object.entries(initial.vendors ?? {}));
  const meta = new Map(Object.entries(initial.meta ?? {}));
  const runs = [...(initial.runs ?? [])];
  return {
    async listObservations() {
      return [...observations.values()].map(item => ({ ...item }));
    },
    async putObservation(observation) {
      observations.set(observation.key, { ...observation });
    },
    async markAttempt({ key, attemptedAt, error }) {
      const existing = observations.get(key) ?? { key, product: {}, price: {}, shipping: {} };
      observations.set(key, { ...existing, attemptedAt, lastError: error ?? null });
    },
    async getVendorState(vendorId) {
      return vendors.has(vendorId) ? { ...vendors.get(vendorId) } : null;
    },
    async setVendorState(vendorId, value) {
      vendors.set(vendorId, { ...value });
    },
    async getMeta(key) {
      return meta.has(key) ? { ...meta.get(key) } : null;
    },
    async setMeta(key, value) {
      if (value == null) meta.delete(key);
      else meta.set(key, { ...value });
    },
    async recordRun(run) {
      runs.push({ ...run });
    },
    async listRuns(limit = 10) {
      return runs.slice(-limit).reverse();
    },
    async acquireLease(name, holderId, ttlMs) {
      const current = meta.get(`lease:${name}`);
      const now = Date.now();
      if (current && current.expiresAt > now && current.holderId !== holderId) return false;
      meta.set(`lease:${name}`, { holderId, expiresAt: now + ttlMs, acquiredAt: new Date(now).toISOString() });
      return true;
    },
    async releaseLease(name) {
      meta.delete(`lease:${name}`);
    },
    async snapshot() {
      return {
        observations: [...observations.values()].map(item => ({ ...item })),
        vendors: Object.fromEntries([...vendors.entries()].map(([id, value]) => [id, { ...value }])),
        runs: runs.slice(-5).reverse(),
        meta: Object.fromEntries(meta)
      };
    }
  };
}

/** File-backed store for the local cron simulation (gitignored path). */
export async function createFileStore(path) {
  const { readFile, writeFile, mkdir } = await import('node:fs/promises');
  const { dirname } = await import('node:path');
  let state = {};
  try {
    state = JSON.parse(await readFile(path, 'utf8'));
  } catch {
    state = { observations: [], vendors: {}, meta: {}, runs: [] };
  }
  const memory = createMemoryStore(state);
  return {
    ...memory,
    async flush() {
      await mkdir(dirname(path), { recursive: true });
      const snapshot = await memory.snapshot();
      await writeFile(path, `${JSON.stringify({ ...snapshot, runs: await memory.listRuns(20) }, null, 2)}\n`);
    }
  };
}

// Scheduled refresh pipeline.
//
// The pipeline is deterministic and bounded: allowlisted hosts, per-request
// timeouts and size limits, concurrency capped, one attempt per offer per run.
// A failing vendor keeps its previous good observation; a missing FX rate keeps
// the previous rate table. Nothing here needs a browser, an LLM or the coding
// loop to be running.

import { createBoundedFetcher } from './lib/http.js';
import { parseBoiRates, FX_SOURCE } from './lib/fx.js';
import { registeredVendors, vendorHosts } from './vendors/index.js';

export const REFRESH_INTERVAL_MS = 6 * 60 * 60 * 1000; // About every six hours.
export const BACKOFF_BASE_MS = 30 * 60 * 1000;
export const BACKOFF_MAX_MS = 12 * 60 * 60 * 1000;
export const LEASE_TTL_MS = 10 * 60 * 1000;
export const MAX_CONCURRENCY = 2;
export const INITIAL_REFRESH_THROTTLE_MS = 10 * 60 * 1000;

export const FX_URL = 'https://www.boi.org.il/currency.xml';
export const FX_HOSTS = ['www.boi.org.il', 'boi.org.il'];

export function backoffMs(consecutiveFailures) {
  if (!consecutiveFailures || consecutiveFailures <= 0) return 0;
  return Math.min(BACKOFF_BASE_MS * 2 ** (consecutiveFailures - 1), BACKOFF_MAX_MS);
}

export function isVendorDue(state, now) {
  if (!state?.nextAttemptAt) return true;
  return Date.parse(state.nextAttemptAt) <= now;
}

export async function runRefresh({
  store,
  vendors = registeredVendors(),
  fetchImpl = globalThis.fetch,
  now = Date.now(),
  includeFx = true,
  trigger = 'scheduled',
  holderId = `refresh-${now}-${Math.random().toString(36).slice(2, 8)}`,
  logger = null
} = {}) {
  const acquired = await store.acquireLease('refresh', holderId, LEASE_TTL_MS);
  if (!acquired) {
    return { skipped: true, reason: 'another refresh holds the lease', trigger };
  }
  const startedAt = new Date(now).toISOString();
  let requests = 0;
  const counter = () => { requests += 1; };
  const fxHosts = FX_HOSTS;
  const results = [];
  try {
    const queued = [];
    for (const vendor of vendors) {
      const state = await store.getVendorState(vendor.id);
      if (!isVendorDue(state, now)) {
        results.push({ vendorId: vendor.id, skipped: true, reason: 'backoff', nextAttemptAt: state.nextAttemptAt });
        continue;
      }
      queued.push({ vendor, state });
    }

    for (let index = 0; index < queued.length; index += MAX_CONCURRENCY) {
      const batch = queued.slice(index, index + MAX_CONCURRENCY);
      const batchResults = await Promise.all(batch.map(({ vendor, state }) => refreshVendor({ store, vendor, state, fetchImpl, now, counter, logger })));
      results.push(...batchResults);
    }

    let fx = null;
    if (includeFx) fx = await refreshFxCached({ store, fetchImpl, now, counter, logger });

    const finishedAt = new Date(Date.now()).toISOString();
    const summary = {
      trigger,
      startedAt,
      finishedAt,
      requests,
      vendors: results,
      fx: fx ? { ok: fx.ok, asOf: fx.fx?.asOf ?? null, error: fx.error ?? null } : { skipped: true }
    };
    await store.recordRun(summary);
    await store.setMeta('lastRefreshAt', { value: finishedAt, trigger });
    return summary;
  } finally {
    await store.releaseLease('refresh');
  }
}

async function refreshVendor({ store, vendor, state, fetchImpl, now, counter, logger }) {
  const fetchText = createBoundedFetcher({
    fetchImpl,
    allowedHosts: vendor.allowedHosts ?? vendorHosts([vendor]),
    onRequest: counter
  });
  const attemptedAt = new Date(now).toISOString();
  let saved = 0;
  const failures = [];
  try {
    const outcome = await vendor.observe({ fetchText, now, logger });
    for (const observation of outcome.observations ?? []) {
      observation.attemptedAt = attemptedAt;
      observation.lastError = null;
      await store.putObservation(observation);
      saved += 1;
    }
    for (const failure of outcome.failures ?? []) {
      failures.push(failure);
      await store.markAttempt({
        key: `${vendor.id}:offer:${failure.offerId}`,
        attemptedAt,
        error: failure.error
      });
    }
  } catch (error) {
    failures.push({ offerId: '*', error: error?.message ?? String(error) });
    for (const offer of vendor.offers ?? []) {
      await store.markAttempt({ key: `${vendor.id}:offer:${offer.id}`, attemptedAt, error: error?.message ?? String(error) });
    }
  }
  const ok = saved > 0;
  const previousFailures = ok ? 0 : (state?.consecutiveFailures ?? 0) + 1;
  const delay = ok ? REFRESH_INTERVAL_MS : Math.max(backoffMs(previousFailures), BACKOFF_BASE_MS);
  const nextAttemptAt = new Date(now + delay).toISOString();
  const nextState = {
    vendorId: vendor.id,
    lastAttemptAt: attemptedAt,
    lastSuccessAt: ok ? attemptedAt : (state?.lastSuccessAt ?? null),
    consecutiveFailures: previousFailures,
    nextAttemptAt,
    lastErrors: failures.map(failure => failure.error).slice(0, 5)
  };
  await store.setVendorState(vendor.id, nextState);
  logger?.info?.(`[refresh] ${vendor.id}: saved=${saved} failures=${failures.length} next=${nextAttemptAt}`);
  return { vendorId: vendor.id, ok, saved, failures, nextAttemptAt };
}

export const FX_MIN_INTERVAL_MS = 3 * 60 * 60 * 1000;

/** Skip the FX fetch when a recent official rate table is already stored. */
export async function refreshFxCached({ store, fetchImpl, now, counter, logger }) {
  const stored = await store.getMeta('fx');
  if (stored?.fetchedAt && now - Date.parse(stored.fetchedAt) < FX_MIN_INTERVAL_MS) {
    return { ok: true, fx: stored, cached: true };
  }
  return refreshFx({ store, fetchImpl, now, counter, logger });
}

export async function refreshFx({ store, fetchImpl, now, counter, logger }) {
  const fetchText = createBoundedFetcher({ fetchImpl, allowedHosts: FX_HOSTS, onRequest: counter });
  const response = await fetchText(FX_URL, { accept: 'application/json' });
  const attemptedAt = new Date(now).toISOString();
  if (!response.ok) {
    logger?.warn?.(`[refresh] fx fetch failed: ${response.error ?? response.status}`);
    return { ok: false, error: response.error ?? `HTTP ${response.status}`, attemptedAt };
  }
  const parsed = (() => {
    try {
      return parseBoiRates(JSON.parse(response.text));
    } catch {
      return null;
    }
  })();
  if (!parsed) return { ok: false, error: 'Bank of Israel feed could not be parsed', attemptedAt };
  const fx = { ...parsed, fetchedAt: attemptedAt, source: FX_SOURCE };
  await store.setMeta('fx', fx);
  return { ok: true, fx, attemptedAt };
}

/**
 * Runs a refresh in the background when the board has never refreshed, for the
 * initial refresh after deployment. Bounded by a lease and a throttle so public
 * traffic can never trigger unlimited scraping.
 */
export async function maybeInitialRefresh({ store, ctx, now = Date.now(), run = runRefresh, ...options } = {}) {
  const last = await store.getMeta('lastRefreshAt');
  if (last?.value) return { skipped: true, reason: 'already refreshed' };
  const attempt = await store.getMeta('initialRefreshAttemptAt');
  if (attempt?.value && now - Date.parse(attempt.value) < INITIAL_REFRESH_THROTTLE_MS) {
    return { skipped: true, reason: 'initial refresh throttled' };
  }
  await store.setMeta('initialRefreshAttemptAt', { value: new Date(now).toISOString() });
  const promise = run({ store, trigger: 'initial', now, ...options }).catch(error => {
    console.warn(`initial refresh failed: ${error?.message ?? error}`);
    return null;
  });
  if (ctx?.waitUntil) ctx.waitUntil(promise);
  return { started: true, promise };
}

// Board client. Fetches the read-only snapshot API and renders the comparison.
// All vendor text is inserted with textContent: fetched pages are untrusted data.

const state = {
  grams: 500,
  destination: 'tel-aviv',
  variant: 'classico',
  showUnknown: true,
  catalog: null,
  board: null,
  error: null
};

const GRAMS_OPTIONS = [250, 500, 750, 1000, 2000];

const ILS = new Intl.NumberFormat('en-IL', { style: 'currency', currency: 'ILS', maximumFractionDigits: 2 });
const IL_TIME = new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Asia/Jerusalem', dateStyle: 'medium', timeStyle: 'short'
});

function el(tag, props = {}, ...children) {
  const node = document.createElement(tag);
  for (const [key, value] of Object.entries(props)) {
    if (value == null) continue;
    if (key === 'class') node.className = value;
    else if (key === 'text') node.textContent = value;
    else if (key === 'dataset') Object.assign(node.dataset, value);
    else if (key.startsWith('on')) node.addEventListener(key.slice(2).toLowerCase(), value);
    else if (key === 'attrs') for (const [a, v] of Object.entries(value)) node.setAttribute(a, v);
    else node[key] = value;
  }
  for (const child of children.flat()) {
    if (child == null) continue;
    node.append(child instanceof Node ? child : document.createTextNode(String(child)));
  }
  return node;
}

function money(amount) {
  return amount == null ? null : ILS.format(amount).replace('₪', '₪');
}

const HEBREW = /[\u0590-\u05FF]/;

/** Wrap Hebrew-containing text in an isolated dir="auto" span so mixed IL/Latin names render correctly. */
function bidi(text) {
  const value = text == null ? '' : String(text);
  if (!HEBREW.test(value)) return value;
  return el('span', { class: 'bidi', attrs: { dir: 'auto', lang: 'he' }, text: value });
}

function timeLabel(iso) {
  if (!iso) return 'never';
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return 'unknown time';
  const hours = (Date.now() - date.getTime()) / 3_600_000;
  const relative = hours < 0.1 ? 'just now' : hours < 1 ? `${Math.round(hours * 60)} min ago` : hours < 48 ? `${Math.round(hours)} h ago` : `${Math.round(hours / 24)} d ago`;
  return `${IL_TIME.format(date)} (${relative})`;
}

function statusBadge(status, label) {
  const kind = status === 'in_stock' ? 'in_stock' : status === 'out_of_stock' ? 'out_of_stock' : 'unknown';
  return el('span', { class: `status status--${kind}`, text: label });
}

function offerLink(quote, label = 'Open the vendor page') {
  return el('a', { href: quote.itemUrl, rel: 'noopener noreferrer nofollow', target: '_blank', text: label });
}

async function load() {
  try {
    const [catalog, board] = await Promise.all([
      fetch('/api/catalog').then(response => response.json()),
      fetch(`/api/board?grams=${state.grams}&dest=${encodeURIComponent(state.destination)}&variant=${encodeURIComponent(state.variant)}`).then(response => response.json())
    ]);
    state.catalog = catalog;
    state.board = board;
    state.error = null;
  } catch (error) {
    state.error = error?.message ?? String(error);
  }
  document.body.dataset.boardState = state.error ? 'error' : 'ready';
  render();
}

function render() {
  renderControls();
  const board = document.getElementById('board');
  board.replaceChildren();
  if (state.error) {
    board.append(el('div', { class: 'empty' },
      el('strong', { text: 'The board could not be loaded.' }),
      el('p', { text: `Reason: ${state.error}. The stored observations are safe; try again in a moment.` })));
    return;
  }
  if (!state.board) return;

  const boardData = state.board;
  board.append(renderRankedSection(boardData));
  if (boardData.pickup.length) board.append(renderPickupSection(boardData.pickup));
  if (state.showUnknown) board.append(renderUnknownSection(boardData));
  board.append(renderFooterStatus(boardData));
}

function renderControls() {
  const quantityGroup = document.getElementById('quantity-group');
  if (!quantityGroup.dataset.ready) {
    for (const grams of GRAMS_OPTIONS) {
      quantityGroup.append(el('button', {
        type: 'button',
        text: grams >= 1000 ? `${grams / 1000} kg` : `${grams} g`,
        dataset: { grams: String(grams) },
        attrs: { 'aria-pressed': String(state.grams === grams) },
        onClick: () => update({ grams })
      }));
    }
    quantityGroup.dataset.ready = 'true';
  }
  for (const button of quantityGroup.querySelectorAll('button')) {
    button.setAttribute('aria-pressed', String(Number(button.dataset.grams) === state.grams));
  }

  const destination = document.getElementById('destination');
  if (state.catalog?.destinations && !destination.dataset.ready) {
    for (const item of state.catalog.destinations) {
      destination.append(el('option', { value: item.id, text: item.postcode ? `${item.label} · ${item.postcode} area` : item.label }));
    }
    destination.dataset.ready = 'true';
    destination.addEventListener('change', () => update({ destination: destination.value }));
  }
  destination.value = state.destination;

  const variant = document.getElementById('variant');
  const variants = state.board?.variants?.length ? state.board.variants : ['classico'];
  const signature = variants.join(',');
  if (variant.dataset.signature !== signature) {
    variant.replaceChildren();
    const labels = { classico: 'Classico (strength 7)', forte: 'Forte', ricco: 'Ricco', risveglio: 'Risveglio', decaf: 'Decaffeinated', unspecified: 'Variant not stated' };
    for (const id of variants) variant.append(el('option', { value: id, text: labels[id] ?? id }));
    variant.dataset.signature = signature;
    variant.addEventListener('change', () => update({ variant: variant.value }));
  }
  variant.value = state.variant;

  const showUnknown = document.getElementById('show-unknown');
  showUnknown.checked = state.showUnknown;
  showUnknown.onchange = () => update({ showUnknown: showUnknown.checked });
}

function update(patch) {
  Object.assign(state, patch);
  const params = new URLSearchParams({
    grams: String(state.grams),
    dest: state.destination,
    variant: state.variant,
    unknown: state.showUnknown ? '1' : '0'
  });
  history.replaceState(null, '', `?${params}`);
  renderControls();
  load();
}

function renderRankedSection(board) {
  const section = el('section', { class: 'section', attrs: { id: 'ranked', 'aria-labelledby': 'ranked-title' } });
  section.append(el('div', { class: 'section__head' },
    el('div', { class: 'section__number', text: '01 / Best known delivered choice' }),
    el('div', {},
      el('h2', { attrs: { id: 'ranked-title' }, text: 'Delivered total, item plus shipping' }),
      el('p', { class: 'section__intro', text: `For ${board.targetGrams} g to ${board.destination.label}. Pack sizes are rounded up to whole packs; the board shows the packs you would actually buy.` }))));

  if (!board.best) {
    section.append(el('div', { class: 'empty' },
      el('strong', { text: 'No offer can be ranked right now.' }),
      el('p', { text: 'Ranking needs a fresh confirmed stock observation, a published shipping price and a stored exchange rate where needed. The observations below explain exactly what is missing.' })));
    return section;
  }

  const best = board.best;
  const main = el('div', { class: 'best__main' },
    el('div', { class: 'best__vendor' }, bidi(best.vendor.name)),
    el('h3', { class: 'best__product' }, bidi(best.product.name ?? 'Lavazza Crema e Gusto')),
    el('p', { class: 'best__variant', text: `${best.product.packCount > 1 ? `${best.product.packCount} × ` : ''}${best.product.packGrams} g vacuum brick · ${best.product.variantLabel}` }),
    el('div', { class: 'best__total-label', text: 'Delivered total for the selected quantity' }),
    el('div', { class: 'best__total', text: money(best.totalIls) }),
    el('div', { class: 'best__perkg', text: best.ilsPerKg != null ? `${money(best.ilsPerKg)} per kilogram · buys ${best.units} pack${best.units === 1 ? '' : 's'} (${best.orderedGrams} g)` : '' }),
    offerLink(best));

  const rows = [
    ['Item price', `${money(best.itemPrice.amount)} ${best.itemPrice.currency} × ${best.units}`],
    ['Shipping', best.shipping.amountIls === 0 ? 'Free' : best.shipping.amountIls != null ? money(best.shipping.amountIls) : 'Unknown'],
    ['Stock', statusBadge(best.availability, best.availabilityLabel)],
    ['Checked', timeLabel(best.observedAt)]
  ];
  if (best.shipping.deliveryTime) rows.push(['Delivery time', best.shipping.deliveryTime]);
  if (best.shipping.pickup?.available) rows.push(['Pickup', 'Free self-pickup is available and shown separately']);
  const side = el('div', { class: 'best__side' });
  const dl = el('dl');
  for (const [term, value] of rows) {
    dl.append(el('dt', { text: term }));
    dl.append(el('dd', {}, value instanceof Node ? value : document.createTextNode(value)));
  }
  side.append(dl);
  if (best.shipping.note) side.append(el('p', { class: 'unknown__reason', text: best.shipping.note }));
  if (best.estimate) side.append(el('p', {}, el('span', { class: 'status status--estimate', text: 'Estimate' }), el('span', { class: 'estimate-note', text: 'includes a converted or estimated component' })));

  section.append(el('div', { class: 'best' }, main, side));

  if (board.ranked.length > 1) {
    section.append(renderCompareTable(board.ranked, board));
  }
  section.append(el('p', { class: 'meta-line', text: `Comparison total = item price + shipping + mandatory fees, converted to ILS where a Bank of Israel reference rate is stored. This is not a personalized checkout quote.` }));
  return section;
}

function renderCompareTable(quotes, board) {
  const table = el('table', { class: 'compare' });
  table.append(el('caption', { text: `All ranked offers for ${board.targetGrams} g to ${board.destination.label}` }));
  const head = el('tr');
  for (const label of ['Vendor', 'Pack / quantity', 'Item price', 'Shipping', 'Delivered total', 'Per kg', 'Stock', 'Checked']) {
    head.append(el('th', { attrs: { scope: 'col' }, text: label }));
  }
  table.append(el('thead', {}, head));
  const body = el('tbody');
  for (const quote of quotes) {
    const row = el('tr');
    row.append(el('td', {}, el('span', { class: 'vendor-name' }, bidi(quote.vendor.name)), el('br'), offerLink(quote, 'Vendor page')));
    row.append(el('td', { class: 'num', text: `${quote.units} × ${quote.product.packGrams} g = ${quote.orderedGrams} g` }));
    row.append(el('td', { class: 'num' , text: `${money(quote.itemPrice.amount)} ${quote.itemPrice.currency}` }));
    row.append(el('td', { class: 'num', text: quote.shipping.amountIls === 0 ? 'Free' : money(quote.shipping.amountIls) }));
    row.append(el('td', { class: 'num' }, el('strong', { text: money(quote.totalIls) }), quote.estimate ? el('span', { class: 'estimate-note', text: ' est.' }) : null));
    row.append(el('td', { class: 'num', text: money(quote.ilsPerKg) }));
    row.append(el('td', {}, statusBadge(quote.availability, quote.availabilityLabel)));
    row.append(el('td', { class: 'num', text: timeLabel(quote.observedAt) }));
    body.append(row);
  }
  table.append(body);
  return el('div', { class: 'table-wrap' }, table);
}

function renderPickupSection(pickup) {
  const section = el('section', { class: 'section', attrs: { id: 'pickup', 'aria-labelledby': 'pickup-title' } });
  section.append(el('div', { class: 'section__head' },
    el('div', { class: 'section__number', text: '02 / Pickup' }),
    el('div', {},
      el('h2', { attrs: { id: 'pickup-title' }, text: 'Pickup options, kept separate' }),
      el('p', { class: 'section__intro', text: 'Pickup is not a delivered price and never competes in the delivered ranking.' }))));
  for (const quote of pickup) {
    section.append(el('div', { class: 'pickup-row' },
      el('div', {}, el('span', { class: 'vendor-name' }, bidi(quote.vendor.name)), el('div', { class: 'unknown__meta' }, bidi(quote.product.name ?? ''))),
      el('div', {},
        el('div', { class: 'unknown__grid' },
          el('span', { text: `Item total for ${quote.units ?? 1} pack(s): ${money(quote.itemTotalIls) ?? 'unknown'}` }),
          el('span', { text: `Pickup fee: ${quote.pickup?.amount?.amount === 0 ? 'Free' : quote.pickup?.amount?.amount != null ? money(quote.pickup.amount.amount) : 'See vendor policy'}` }),
          el('span', { text: `Checked ${timeLabel(quote.observedAt)}` })),
        el('p', { class: 'unknown__reason', text: [quote.pickup?.note, quote.labels.join('. ')].filter(Boolean).join(' ') }),
        offerLink(quote))));
  }
  return section;
}

function renderUnknownSection(board) {
  const section = el('section', { class: 'section', attrs: { id: 'unknown', 'aria-labelledby': 'unknown-title' } });
  section.append(el('div', { class: 'section__head' },
    el('div', { class: 'section__number', text: '03 / Not comparable yet' }),
    el('div', {},
      el('h2', { attrs: { id: 'unknown-title' }, text: 'Offers with missing information' }),
      el('p', { class: 'section__intro', text: 'These observations stay visible with their source, timestamp and the exact reason a delivered total cannot be calculated. Missing shipping or currency data is never treated as zero.' }))));

  const entries = [...board.unrankable, ...board.staleOrUnavailable];
  if (!entries.length) {
    section.append(el('p', { class: 'meta-line', text: 'Nothing is missing right now: every stored offer has enough verified information to compare.' }));
    return section;
  }
  const list = el('div', { class: 'unknown-list' });
  for (const quote of entries) {
    const shipped = quote.shipping.amountIls != null
      ? (quote.shipping.amountIls === 0 ? 'Free' : money(quote.shipping.amountIls))
      : (quote.shipping.amount != null ? `${money(quote.shipping.amount)} ${quote.shipping.currency} (not converted)` : 'Unknown');
    list.append(el('article', { class: 'unknown' },
      el('div', {},
        el('div', { class: 'unknown__vendor' }, bidi(quote.vendor.name)),
        el('div', { class: 'unknown__meta' }, bidi(quote.product.name ?? '')),
        el('div', { class: 'unknown__meta', text: `Variant: ${quote.product.variantLabel} · Pack: ${quote.product.packCount} × ${quote.product.packGrams ?? '?'} g` })),
      el('div', {},
        el('div', { class: 'unknown__grid' },
          el('span', {}, statusBadge(quote.availability, quote.availabilityLabel)),
          el('span', { text: `Item price: ${quote.itemPrice.amount != null ? `${money(quote.itemPrice.amount)} ${quote.itemPrice.currency}` : 'unknown'}` }),
          el('span', { text: `Shipping: ${shipped}` }),
          el('span', { text: `Last successful check: ${timeLabel(quote.observedAt)}` }),
          el('span', { text: `Last attempt: ${timeLabel(quote.attemptedAt)}` })),
        el('p', { class: 'unknown__reason', text: quote.reasons.join('. ') || quote.labels.join('. ') || 'Not enough verified information yet.' }),
        quote.labels.length ? el('p', { class: 'unknown__meta', text: quote.labels.join(' · ') }) : null,
        el('p', {}, offerLink(quote, 'Check this vendor page')))));
  }
  section.append(list);
  return section;
}

function renderFooterStatus(board) {
  const vendors = board.freshness?.vendors ?? [];
  const failing = vendors.filter(vendor => (vendor.consecutiveFailures ?? 0) > 0);
  const wrap = el('div', { class: 'meta-line' });
  wrap.append(el('div', { text: `Board refreshed: ${timeLabel(board.freshness?.lastRefreshAt)} · Offers observed for this variant: ${board.counts.observed} · Ranked: ${board.counts.ranked}` }));
  if (board.freshness?.fx) {
    wrap.append(el('div', { text: `Exchange rates: ${board.freshness.fx.source ?? 'Bank of Israel'} published ${board.freshness.fx.asOf ?? 'unknown'} · fetched ${timeLabel(board.freshness.fx.fetchedAt)}` }));
  } else {
    wrap.append(el('div', { text: 'Exchange rates: no official rate table stored yet, so foreign-currency offers cannot be ranked.' }));
  }
  for (const vendor of vendors) {
    wrap.append(el('div', { text: `${vendor.vendorId}: last success ${timeLabel(vendor.lastSuccessAt)} · last attempt ${timeLabel(vendor.lastAttemptAt)}` }));
  }
  if (failing.length) {
    wrap.append(el('div', { class: 'status status--stale', text: `${failing.length} source(s) failing` }));
    for (const vendor of failing) {
      wrap.append(el('div', { text: `${vendor.vendorId}: ${vendor.consecutiveFailures} consecutive failure(s) · next attempt ${timeLabel(vendor.nextAttemptAt)}${vendor.lastErrors?.[0] ? ` · last error: ${vendor.lastErrors[0]}` : ''}` }));
    }
  }
  return wrap;
}

const params = new URLSearchParams(location.search);
state.grams = Number(params.get('grams')) || 500;
state.destination = params.get('dest') || 'tel-aviv';
state.variant = params.get('variant') || 'classico';
state.showUnknown = params.get('unknown') !== '0';
load();

// Pure quote and ranking engine.
//
// Comparison total = item price + shipping + mandatory fees, normalized to ILS.
// Unknown shipping, unknown FX, stale observations, unknown availability and
// out-of-stock observations never become zero and never win.
// Pickup options are kept separate from delivered offers.

import { toIls } from './fx.js';

export const DEFAULT_STALE_AFTER_MS = 24 * 60 * 60 * 1000;
export const CLOCK_SKEW_MS = 5 * 60 * 1000;

export const DESTINATIONS = [
  { id: 'tel-aviv', label: 'Tel Aviv–Yafo', postcode: '6100000', country: 'IL' },
  { id: 'jerusalem', label: 'Jerusalem', postcode: '9100000', country: 'IL' },
  { id: 'haifa', label: 'Haifa', postcode: '3100000', country: 'IL' },
  { id: 'beer-sheva', label: "Be'er Sheva", postcode: '8400000', country: 'IL' },
  { id: 'eilat', label: 'Eilat', postcode: '8800000', country: 'IL' },
  { id: 'other', label: 'Elsewhere in Israel', postcode: null, country: 'IL' }
];

export function findDestination(id) {
  return DESTINATIONS.find(item => item.id === id) ?? DESTINATIONS[DESTINATIONS.length - 1];
}

const AVAILABILITY_LABELS = {
  in_stock: 'In stock (observed)',
  out_of_stock: 'Out of stock (observed)',
  unknown: 'Availability unknown'
};

export function quoteBoard({
  observations = [],
  productId,
  variantId = null,
  targetGrams = 500,
  destination = DESTINATIONS[0],
  fx = null,
  now = Date.now(),
  staleAfterMs = DEFAULT_STALE_AFTER_MS
} = {}) {
  const grams = clampGrams(targetGrams);
  const quotes = [];
  const variants = new Set();
  for (const observation of observations) {
    if (productId && observation?.product?.productId !== productId) continue;
    if (observation?.product?.form !== 'ground') continue;
    variants.add(observation?.product?.variantId ?? 'unspecified');
    if (variantId && (observation?.product?.variantId ?? 'unspecified') !== variantId) continue;
    quotes.push(quoteOffer(observation, { grams, destination, fx, now, staleAfterMs }));
  }
  const ranked = quotes.filter(quote => quote.rankable).sort(compareQuotes);
  const pickup = [
    ...quotes.filter(quote => quote.group === 'pickup'),
    ...quotes
      .filter(quote => quote.group !== 'pickup' && quote.shipping?.pickup?.available)
      .map(toPickupEntry)
  ];
  const unrankable = quotes.filter(quote => quote.group === 'unrankable');
  const staleOrUnavailable = quotes.filter(quote => quote.group === 'stale_unavailable');
  const unknown = [...unrankable, ...staleOrUnavailable];
  return {
    productId,
    variantId,
    variants: [...variants].sort(),
    targetGrams: grams,
    destination,
    generatedAt: new Date(now).toISOString(),
    fx: fx ? { asOf: fx.asOf ?? null, source: fx.source?.name ?? null } : null,
    best: ranked[0] ?? null,
    ranked,
    pickup,
    unrankable,
    staleOrUnavailable,
    unknown,
    counts: {
      observed: quotes.length,
      ranked: ranked.length,
      pickup: pickup.length,
      unknown: unknown.length
    }
  };
}

export function quoteOffer(observation, { grams, destination, fx, now, staleAfterMs }) {
  const product = observation.product ?? {};
  const price = observation.price ?? {};
  const shipping = observation.shipping ?? {};
  const reasons = [];
  const labels = [];

  const ageMs = observation.observedAt ? now - Date.parse(observation.observedAt) : null;
  const stale = ageMs == null || ageMs > staleAfterMs || ageMs < -CLOCK_SKEW_MS;
  const freshness = ageMs == null ? 'unknown' : stale ? 'stale' : 'fresh';

  const base = {
    key: observation.key,
    vendor: observation.vendor,
    itemUrl: observation.itemUrl,
    product: {
      productId: product.productId,
      name: product.name ?? null,
      variantId: product.variantId ?? 'unspecified',
      variantLabel: product.variantLabel ?? 'Variant not stated',
      form: product.form,
      packGrams: product.packGrams ?? null,
      packCount: product.packCount ?? 1,
      totalGrams: product.totalGrams ?? null,
      sku: product.sku ?? null
    },
    availability: observation.availability ?? 'unknown',
    availabilityLabel: AVAILABILITY_LABELS[observation.availability] ?? AVAILABILITY_LABELS.unknown,
    freshness,
    ageHours: ageMs == null ? null : Math.round((ageMs / 3_600_000) * 10) / 10,
    observedAt: observation.observedAt ?? null,
    attemptedAt: observation.attemptedAt ?? null,
    evidence: observation.evidence ?? [],
    units: null,
    orderedGrams: null,
    itemPrice: { amount: price.amount ?? null, currency: price.currency ?? null },
    itemTotalIls: null,
    shipping: {
      mode: shipping.mode ?? 'delivery',
      certainty: shipping.certainty ?? 'unknown',
      amount: shipping.amount?.amount ?? null,
      currency: shipping.amount?.currency ?? null,
      amountIls: null,
      freeThreshold: shipping.freeThreshold?.amount ?? null,
      freeThresholdCurrency: shipping.freeThreshold?.currency ?? null,
      minOrder: shipping.minOrder?.amount ?? null,
      minOrderCurrency: shipping.minOrder?.currency ?? null,
      destination: shipping.destination ?? { scope: 'country', country: 'IL' },
      deliveryTime: shipping.deliveryTime ?? null,
      pickup: shipping.pickup ?? null,
      note: shipping.note ?? null,
      evidence: shipping.evidence ?? null
    },
    mandatoryFees: [],
    totalIls: null,
    ilsPerKg: null,
    estimate: false,
    rankable: false,
    reasons,
    labels,
    group: 'unrankable'
  };

  if (observation.shipping?.mode === 'pickup') {
    base.group = 'pickup';
    base.labels.push('Pickup only — not a delivered offer');
    if (product.totalGrams) {
      base.units = Math.max(1, Math.ceil(grams / product.totalGrams));
      base.orderedGrams = base.units * product.totalGrams;
    }
    const pickupTotal = toIls(price.amount == null ? null : price.amount * (base.units ?? 1), price.currency, fx);
    if (pickupTotal.known) {
      base.itemTotalIls = round2(pickupTotal.amount);
      base.labels.push('Shown for pickup comparison only');
    }
    return base;
  }

  if (!product.totalGrams || !product.packGrams) {
    reasons.push('Pack weight is not stated, so the delivered price per kilogram cannot be calculated');
    return base;
  }

  const units = Math.max(1, Math.ceil(grams / product.totalGrams));
  base.units = units;
  base.orderedGrams = units * product.totalGrams;

  const itemTotal = toIls(price.amount == null ? null : price.amount * units, price.currency, fx);
  if (!itemTotal.known) {
    reasons.push(price.amount == null
      ? 'Item price was not observed'
      : `No ${price.currency} reference rate is stored, so the total cannot be converted to ILS`);
    if (price.amount != null && Number.isFinite(price.amount)) {
      base.itemPrice.amount = round2(price.amount * units);
    }
    return base;
  }
  base.itemTotalIls = round2(itemTotal.amount);
  if (itemTotal.converted) base.estimate = true;

  if (shipping.minOrder != null) {
    const min = toIls(shipping.minOrder.amount, shipping.minOrder.currency ?? price.currency, fx);
    if (min.known && base.itemTotalIls < min.amount - 0.005) {
      reasons.push(`Order is below the vendor minimum order of ${formatAmount(min.amount, 'ILS')}`);
      return base;
    }
  }

  const coverage = coverageProblem(shipping.destination, destination);
  if (coverage) {
    reasons.push(coverage);
    return base;
  }

  if (observation.availability === 'out_of_stock') {
    base.labels.push('Out of stock at last successful check');
    base.group = 'stale_unavailable';
    return base;
  }
  if (observation.availability !== 'in_stock') {
    reasons.push('Stock was not confirmed by the source, so this offer cannot be confirmed as available');
    base.group = 'stale_unavailable';
    return base;
  }

  const feeSum = { amount: 0, currency: 'ILS' };
  for (const fee of observation.mandatoryFees ?? []) {
    const converted = toIls(fee.amount, fee.currency, fx);
    if (!converted.known) {
      reasons.push(`A mandatory fee (${fee.label ?? 'unlabelled'}) could not be converted to ILS`);
      return base;
    }
    feeSum.amount += converted.amount;
    base.mandatoryFees.push({ label: fee.label ?? 'Mandatory fee', amountIls: round2(converted.amount) });
  }

  let shippingIls = null;
  if (shipping.certainty === 'unknown' || shipping.amount == null) {
    reasons.push(shipping.note
      ? `Shipping is not published before checkout, so it is treated as unknown, not free (${shipping.note})`
      : 'Shipping is not published before checkout, so it is treated as unknown, not free');
    return base;
  }
  const convertedShipping = toIls(shipping.amount.amount ?? shipping.amount, shipping.amount.currency ?? price.currency, fx);
  if (!convertedShipping.known) {
    reasons.push(`Shipping is quoted in ${shipping.amount.currency ?? 'an unknown currency'} with no stored reference rate`);
    return base;
  }
  shippingIls = convertedShipping.amount;
  if (convertedShipping.converted || shipping.certainty === 'estimated') base.estimate = true;

  if (shipping.freeThreshold != null) {
    const threshold = toIls(shipping.freeThreshold.amount, shipping.freeThreshold.currency, fx);
    if (threshold.known && base.itemTotalIls >= threshold.amount - 0.005) {
      shippingIls = 0;
      base.labels.push(`Free shipping threshold met (${formatAmount(threshold.amount, 'ILS')})`);
    }
  }

  base.shipping.amountIls = round2(shippingIls);
  if (stale) {
    labels.push('Stale observation — the last successful check is too old to rank');
    base.group = 'stale_unavailable';
    return base;
  }

  base.totalIls = round2(base.itemTotalIls + shippingIls + feeSum.amount);
  base.ilsPerKg = round2((base.totalIls / base.orderedGrams) * 1000);
  base.rankable = true;
  base.group = 'ranked';
  if (base.estimate) labels.push('Estimate — includes a converted or estimated component');
  return base;
}

function coverageProblem(shippingDestination, destination) {
  if (!shippingDestination) return null;
  if (shippingDestination.scope === 'country') {
    if (destination?.country && shippingDestination.country !== destination.country) {
      return `Vendor does not deliver to ${destination.country}`;
    }
    return null;
  }
  if (shippingDestination.scope === 'localities') {
    const localities = shippingDestination.localities ?? [];
    if (!destination?.id || !localities.includes(destination.id)) {
      return `Vendor delivery list does not include ${destination?.label ?? 'this destination'}`;
    }
    return null;
  }
  return 'Vendor delivery coverage is not documented';
}

function toPickupEntry(quote) {
  const itemTotal = quote.itemTotalIls ?? (quote.itemPrice.amount != null && quote.units
    ? round2(quote.itemPrice.amount * quote.units)
    : null);
  return {
    ...quote,
    key: `${quote.key}:pickup`,
    group: 'pickup',
    rankable: false,
    totalIls: null,
    ilsPerKg: null,
    itemTotalIls: itemTotal,
    pickup: {
      available: true,
      amount: quote.shipping.pickup?.amount ?? null,
      note: quote.shipping.pickup?.note ?? null
    },
    labels: [...quote.labels, 'Pickup only — not a delivered offer']
  };
}

function compareQuotes(a, b) {
  if (a.totalIls !== b.totalIls) return a.totalIls - b.totalIls;
  if (a.ilsPerKg !== b.ilsPerKg) return a.ilsPerKg - b.ilsPerKg;
  return String(a.vendor?.name ?? '').localeCompare(String(b.vendor?.name ?? ''));
}

export function clampGrams(value) {
  const grams = Number(value);
  if (!Number.isFinite(grams) || grams <= 0) return 500;
  return Math.min(Math.max(Math.round(grams), 1), 100_000);
}

export function formatAmount(amount, currency = 'ILS') {
  const symbols = { ILS: '₪', USD: '$', EUR: '€', GBP: '£' };
  const symbol = symbols[String(currency).toUpperCase()] ?? `${currency} `;
  return `${symbol}${Number(amount).toFixed(2)}`;
}

function round2(value) {
  return Math.round(value * 100) / 100;
}

// CoffeeMan / Amigo (coffeeman.co.il), Israel — Lavazza Crema e Gusto Classico 250 g ground.
// The page is a legacy Windows-1255 HTML document with schema.org microdata.
// Price, listed availability, SKU and the published delivery options are parsed
// from the product page. Free self-pickup is kept separate from home delivery.

import { classifyListing } from '../catalog.js';
import { decodeHtml, parseDecimal, stripTags, collapse } from '../lib/text.js';
import { createObservation, parseError } from './index.js';

const PRODUCT_URL = 'https://www.coffeeman.co.il/product/250-%D7%92%D7%A8%D7%9D-%D7%A7%D7%A4%D7%94-%D7%98%D7%97%D7%95%D7%9F-lavazza-crema-e-gusto-classico';

const AVAILABILITY = {
  InStock: 'in_stock',
  LimitedAvailability: 'in_stock',
  OutOfStock: 'out_of_stock',
  SoldOut: 'out_of_stock',
  PreOrder: 'unknown'
};

export const coffeeman = {
  id: 'coffeeman',
  name: 'CoffeeMan (אמיגו)',
  homepage: 'https://www.coffeeman.co.il',
  allowedHosts: ['www.coffeeman.co.il', 'coffeeman.co.il'],
  parserVersion: 'coffeeman/1',
  offers: [{ id: 'classico-250g', url: PRODUCT_URL, kind: 'delivery' }],

  async observe({ fetchText, now }) {
    const observations = [];
    const failures = [];
    for (const offer of this.offers) {
      const response = await fetchText(offer.url, { accept: 'text/html' });
      if (!response.ok) {
        failures.push({ offerId: offer.id, url: offer.url, error: response.error ?? `HTTP ${response.status}` });
        continue;
      }
      try {
        const html = response.buffer ? decodeHtml(response.buffer, response.text) : response.text;
        observations.push(parseCoffeemanProduct(html, { now }));
      } catch (error) {
        failures.push({ offerId: offer.id, url: offer.url, error: error.message, details: error.details ?? null });
      }
    }
    return { observations, failures };
  }
};

export function parseCoffeemanProduct(html, { now } = {}) {
  const name = extractName(html);
  if (!name) throw parseError('Product name not found', { url: PRODUCT_URL });
  const classification = classifyListing(name);
  if (!classification.matched) {
    throw parseError('Listing does not match the tracked product', { name, reasons: classification.reasons });
  }

  const priceMatch = /itemprop="price"[^>]*\bprice="([\d.,]+)"/.exec(html) ?? /itemprop="price"[^>]*\bcontent="([\d.,]+)"/.exec(html);
  const priceAmount = parseDecimal(priceMatch?.[1]);
  if (priceAmount == null) throw parseError('Price not found in product microdata', { name });
  const currency = /itemprop="priceCurrency"\s*>\s*([A-Z]{3})/.exec(html)?.[1] ?? null;
  if (!currency) throw parseError('Currency not found in product microdata', { name });

  const regularMatch = /\bprice="([\d.,]+)"\s+id="total_regularprice"/.exec(html) ?? /\bprice="([\d.,]+)"[^>]*class="toal_regularprice_view"/.exec(html);
  const regularPrice = parseDecimal(regularMatch?.[1]);

  const availabilityHref = /itemprop="availability"[^>]*href="([^"]+)"/.exec(html)?.[1] ?? '';
  const availability = AVAILABILITY[availabilityHref.split('/').pop()] ?? 'unknown';
  const sku = /itemprop="sku"[^>]*>([^<]+)</.exec(html)?.[1]?.trim()
    ?? /מקט:\s*(\d+)/.exec(html)?.[1]
    ?? null;
  const deliveryTime = collapse(/זמן\s*אספקה\s*:\s*([^<\n]+)/.exec(html)?.[1] ?? '');

  const shipping = parseShippingOptions(html);
  const observation = createObservation({
    vendor: coffeeman,
    itemUrl: PRODUCT_URL,
    product: {
      productId: classification.productId,
      name,
      sku,
      gtin: null,
      variantId: classification.variantId,
      variantLabel: classification.variantLabel,
      form: classification.form,
      packGrams: classification.packGrams,
      packCount: classification.packCount,
      totalGrams: classification.totalGrams,
      category: 'קפה טחון'
    },
    price: { amount: priceAmount, currency, regularAmount: regularPrice },
    availability,
    availabilityEvidence: {
      url: PRODUCT_URL,
      value: availabilityHref || 'not stated',
      note: 'Availability comes from the product page offer microdata, not from a price-only scrape.'
    },
    shipping: {
      mode: 'delivery',
      certainty: shipping.deliveryCents == null ? 'unknown' : 'verified',
      amount: shipping.deliveryCents == null ? null : { amount: shipping.deliveryCents, currency },
      destination: { scope: 'country', country: 'IL' },
      minOrder: null,
      freeThreshold: null,
      note: shipping.note,
      deliveryTime: deliveryTime || null,
      pickup: {
        available: shipping.pickupFree,
        amount: shipping.pickupFree ? { amount: 0, currency } : null,
        note: shipping.pickupFree ? 'Free self-pickup, listed on the product page.' : null
      },
      evidence: { url: PRODUCT_URL, retrievedAt: null, note: 'Delivery options are listed on the product page.' }
    },
    now
  });
  return observation;
}

export function parseShippingOptions(html) {
  const start = html.indexOf('delivery-price-product');
  const block = start >= 0 ? html.slice(start, start + 2500) : '';
  const items = [...block.matchAll(/<li[^>]*>([\s\S]*?)<\/li>/gi)].map(match => collapse(stripTags(match[1])));
  let deliveryCents = null;
  let pickupFree = false;
  let distributionCenter = null;
  for (const item of items) {
    if (item.includes('איסוף עצמי')) {
      pickupFree = true;
    } else if (item.includes('שליח')) {
      const amount = parseDecimal(item.match(/([\d.,]+)/)?.[1]);
      if (amount != null) deliveryCents = amount;
    } else if (item.includes('מרכז חלוקה')) {
      distributionCenter = item;
    }
  }
  const notes = [];
  if (deliveryCents != null) {
    notes.push(`Published courier delivery rate: ₪${deliveryCents.toFixed(2)}.`);
  } else {
    notes.push('No published courier rate found; delivery cost is unknown before checkout.');
  }
  if (distributionCenter) {
    notes.push('A distribution-center delivery option exists, but its price is not published on the product page.');
  }
  if (pickupFree) {
    notes.push('Free self-pickup is available and is kept separate from delivery.');
  }
  return { deliveryCents, pickupFree, distributionCenter, note: notes.join(' ') };
}

function extractName(html) {
  const h1 = /<h1[^>]*itemprop="name"[^>]*>([\s\S]*?)<\/h1>/i.exec(html)?.[1];
  if (h1) return collapse(stripTags(h1));
  const og = /<meta\s+property="og:title"\s+content\s*=\s*"([^"]+)"/i.exec(html)?.[1];
  if (og) return collapse(String(og).replace(/\s*-\s*₪[\d.,]+\s*$/, ''));
  const title = /<title>([\s\S]*?)<\/title>/i.exec(html)?.[1];
  return title ? collapse(stripTags(title).split('|')[0]) : null;
}

